// SMC, ICT, SK System lesson data

export const smcLessons = [
  { id: 1, diagram: 'market-structure', en: { title: "Introduction to Smart Money Concepts", content: "Smart Money Concepts (SMC) is a trading methodology that focuses on understanding how institutional traders (banks, hedge funds) move the market. Unlike retail trading, SMC looks at the market from the perspective of the 'smart money' — the big players who actually drive price.\n\nThe key idea is that markets are not random. They are manipulated by institutions to create liquidity, trap retail traders, and fill their large orders. By understanding this, you can trade alongside the smart money instead of against them.", steps: ["Understand that institutions control market movements", "Learn to see the market from the smart money perspective", "Recognize that retail traders are often used as liquidity", "Study how institutions accumulate and distribute positions", "Learn the key SMC concepts: structure, liquidity, order blocks"], example: "When you see a sudden spike down that takes out everyone's stop losses, then price immediately reverses up — that's smart money hunting liquidity to fill their buy orders.", keyTakeaways: ["SMC focuses on institutional trading behavior", "Markets are driven by smart money, not retail traders", "Institutions need liquidity to fill large orders", "Understanding this gives you a significant edge"] }, ar: { title: "مقدمة في مفاهيم المال الذكي", content: "مفاهيم المال الذكي (SMC) هي منهجية تداول تركز على فهم كيف يحرك المتداولون المؤسسيون (البنوك، صناديق التحوط) السوق.\n\nالفكرة الأساسية هي أن الأسواق ليست عشوائية. يتم التلاعب بها من قبل المؤسسات لخلق السيولة واصطياد المتداولين الأفراد وملء أوامرهم الكبيرة.", steps: ["افهم أن المؤسسات تتحكم في حركات السوق", "تعلم رؤية السوق من منظور المال الذكي", "اعرف أن المتداولين الأفراد يُستخدمون كسيولة", "ادرس كيف تجمع المؤسسات وتوزع مراكزها", "تعلم مفاهيم SMC الأساسية"], example: "عندما ترى هبوطاً مفاجئاً يأخذ وقف خسارة الجميع ثم ينعكس السعر فوراً — هذا المال الذكي يصطاد السيولة.", keyTakeaways: ["SMC يركز على سلوك التداول المؤسسي", "الأسواق يحركها المال الذكي", "المؤسسات تحتاج السيولة لملء أوامرها", "فهم هذا يمنحك ميزة كبيرة"] }, fr: { title: "Introduction aux Smart Money Concepts", content: "Les SMC se concentrent sur le comportement des institutions dans le marché.", steps: ["Comprenez le rôle des institutions", "Voyez le marché comme le smart money", "Reconnaissez la liquidité", "Étudiez l'accumulation", "Apprenez les concepts clés"], example: "Un spike baissier qui prend les stops puis remonte = chasse à la liquidité.", keyTakeaways: ["Focus sur les institutions", "Le marché n'est pas aléatoire", "Les institutions chassent la liquidité", "Avantage significatif"] }, es: { title: "Introducción a Smart Money Concepts", content: "SMC se enfoca en entender cómo las instituciones mueven el mercado.", steps: ["Entiende el rol institucional", "Ve el mercado como smart money", "Reconoce la liquidez", "Estudia la acumulación", "Aprende conceptos clave"], example: "Un spike bajista que toma stops y luego sube = caza de liquidez.", keyTakeaways: ["Enfoque institucional", "Mercado no aleatorio", "Instituciones cazan liquidez", "Ventaja significativa"] } },
  { id: 2, diagram: 'market-structure', en: { title: "Market Structure in SMC", content: "Market structure is the foundation of SMC. It describes the pattern of highs and lows that price creates.\n\n**Bullish Structure:** Higher Highs (HH) and Higher Lows (HL)\n**Bearish Structure:** Lower Highs (LH) and Lower Lows (LL)\n\nA **Break of Structure (BOS)** occurs when price breaks a previous high (bullish) or low (bearish), confirming the trend continuation.\n\nA **Change of Character (CHoCH)** occurs when the structure shifts — for example, from making higher highs to making a lower low. This signals a potential trend reversal.", steps: ["Identify swing highs and swing lows on your chart", "Label them as HH, HL, LH, or LL", "Mark Break of Structure (BOS) when trend continues", "Mark Change of Character (CHoCH) when structure shifts", "Trade in the direction of the confirmed structure"], example: "Price makes HH at 1.1050, HL at 1.1000, then breaks above 1.1050 to make a new HH — this is a bullish BOS. If price then makes a lower low below 1.1000, that's a CHoCH signaling potential bearish reversal.", keyTakeaways: ["BOS = trend continuation signal", "CHoCH = potential trend reversal signal", "Always identify the current market structure first", "Trade with the structure, not against it"] }, ar: { title: "هيكل السوق في SMC", content: "هيكل السوق هو أساس SMC. يصف نمط القمم والقيعان.\n\n**هيكل صعودي:** قمم أعلى (HH) وقيعان أعلى (HL)\n**هيكل هبوطي:** قمم أدنى (LH) وقيعان أدنى (LL)\n\n**كسر الهيكل (BOS)** يحدث عندما يكسر السعر قمة سابقة أو قاع.\n**تغيير الطابع (CHoCH)** يحدث عندما يتغير الهيكل.", steps: ["حدد القمم والقيعان المتأرجحة", "صنفها كـ HH, HL, LH, LL", "حدد كسر الهيكل (BOS)", "حدد تغيير الطابع (CHoCH)", "تداول في اتجاه الهيكل المؤكد"], example: "السعر يصنع HH عند 1.1050، HL عند 1.1000، ثم يكسر فوق 1.1050 — هذا BOS صعودي.", keyTakeaways: ["BOS = إشارة استمرار الاتجاه", "CHoCH = إشارة انعكاس محتمل", "حدد هيكل السوق الحالي أولاً", "تداول مع الهيكل"] }, fr: { title: "Structure du Marché SMC", content: "La structure du marché décrit les patterns de hauts et bas. BOS confirme la tendance, CHoCH signale un retournement.", steps: ["Identifiez les swings", "Classifiez HH/HL/LH/LL", "Marquez les BOS", "Marquez les CHoCH", "Tradez avec la structure"], example: "HH à 1.1050, HL à 1.1000, cassure au-dessus = BOS haussier.", keyTakeaways: ["BOS = continuation", "CHoCH = retournement", "Structure d'abord", "Tradez avec la structure"] }, es: { title: "Estructura del Mercado SMC", content: "La estructura describe los patrones de máximos y mínimos. BOS confirma tendencia, CHoCH señala reversión.", steps: ["Identifica los swings", "Clasifica HH/HL/LH/LL", "Marca los BOS", "Marca los CHoCH", "Opera con la estructura"], example: "HH en 1.1050, HL en 1.1000, ruptura arriba = BOS alcista.", keyTakeaways: ["BOS = continuación", "CHoCH = reversión", "Estructura primero", "Opera con la estructura"] } },
  { id: 3, diagram: 'liquidity', en: { title: "Liquidity Concepts", content: "Liquidity in SMC refers to clusters of stop loss orders sitting at obvious price levels. Institutions need this liquidity to fill their large orders.\n\n**Types of Liquidity:**\n- **Buy-side Liquidity (BSL):** Stop losses above swing highs. Institutions drive price up to grab these before reversing down.\n- **Sell-side Liquidity (SSL):** Stop losses below swing lows. Institutions drive price down to grab these before reversing up.\n- **Equal Highs/Lows:** Multiple touches at the same level create a pool of liquidity.\n\nUnderstanding liquidity helps you avoid being the victim and instead trade with the smart money.", steps: ["Identify obvious swing highs and lows", "Mark equal highs and equal lows", "Understand that stop losses cluster at these levels", "Wait for liquidity to be swept before entering", "Enter in the opposite direction after a liquidity grab"], example: "Price has bounced off 1.0800 three times, creating equal lows. Many traders have buy stops just below. Smart money pushes price below 1.0800 to grab those stops, then reverses up sharply. You enter long after the sweep.", keyTakeaways: ["Liquidity = clusters of stop loss orders", "BSL above highs, SSL below lows", "Institutions hunt liquidity to fill orders", "Trade after liquidity is swept, not before"] }, ar: { title: "مفاهيم السيولة", content: "السيولة في SMC تشير إلى تجمعات أوامر وقف الخسارة عند مستويات سعرية واضحة.\n\n**أنواع السيولة:**\n- **سيولة جانب الشراء (BSL):** وقف خسارة فوق القمم\n- **سيولة جانب البيع (SSL):** وقف خسارة تحت القيعان\n- **قمم/قيعان متساوية:** لمسات متعددة عند نفس المستوى", steps: ["حدد القمم والقيعان الواضحة", "حدد القمم والقيعان المتساوية", "افهم أن وقف الخسارة يتجمع عند هذه المستويات", "انتظر اكتساح السيولة قبل الدخول", "ادخل في الاتجاه المعاكس بعد اصطياد السيولة"], example: "السعر ارتد من 1.0800 ثلاث مرات. المال الذكي يدفع السعر تحت 1.0800 لاصطياد الأوامر ثم ينعكس صعوداً.", keyTakeaways: ["السيولة = تجمعات أوامر وقف الخسارة", "BSL فوق القمم، SSL تحت القيعان", "المؤسسات تصطاد السيولة", "تداول بعد اكتساح السيولة"] }, fr: { title: "Concepts de Liquidité", content: "La liquidité = clusters de stop loss. BSL au-dessus des hauts, SSL en dessous des bas. Les institutions chassent cette liquidité.", steps: ["Identifiez les swings", "Marquez les equal highs/lows", "Comprenez les clusters de stops", "Attendez le sweep", "Entrez après le sweep"], example: "Le prix rebondit 3 fois sur 1.0800. Le smart money pousse en dessous puis remonte.", keyTakeaways: ["Liquidité = clusters de stops", "BSL/SSL", "Institutions chassent", "Tradez après le sweep"] }, es: { title: "Conceptos de Liquidez", content: "Liquidez = clusters de stop loss. BSL arriba de máximos, SSL debajo de mínimos. Las instituciones cazan esta liquidez.", steps: ["Identifica los swings", "Marca equal highs/lows", "Entiende clusters de stops", "Espera el sweep", "Entra después del sweep"], example: "El precio rebota 3 veces en 1.0800. Smart money empuja abajo y luego sube.", keyTakeaways: ["Liquidez = clusters de stops", "BSL/SSL", "Instituciones cazan", "Opera después del sweep"] } },
  { id: 4, diagram: 'order-blocks', en: { title: "Order Blocks", content: "An Order Block (OB) is the last candle before a strong impulsive move. It represents the area where institutions placed their orders.\n\n**Bullish Order Block:** The last bearish (red) candle before a strong move up. This is where institutions were buying.\n\n**Bearish Order Block:** The last bullish (green) candle before a strong move down. This is where institutions were selling.\n\nWhen price returns to an order block, it often bounces because institutions defend their positions.", steps: ["Identify a strong impulsive move (multiple candles in one direction)", "Find the last opposite-color candle before the move", "Mark the high and low of that candle as the order block zone", "Wait for price to return to this zone", "Enter when price shows rejection at the order block"], example: "Price drops sharply from 1.1000. The last green candle before the drop was at 1.0990-1.1000. When price returns to this zone, it gets rejected and drops again. This is a bearish order block.", keyTakeaways: ["OB = last candle before impulsive move", "Bullish OB = last red candle before move up", "Bearish OB = last green candle before move down", "Price often reacts at order blocks"] }, ar: { title: "كتل الأوامر", content: "كتلة الأوامر (OB) هي آخر شمعة قبل حركة اندفاعية قوية. تمثل المنطقة التي وضعت فيها المؤسسات أوامرها.\n\n**كتلة أوامر صعودية:** آخر شمعة هبوطية قبل حركة صعود قوية.\n**كتلة أوامر هبوطية:** آخر شمعة صعودية قبل حركة هبوط قوية.", steps: ["حدد حركة اندفاعية قوية", "ابحث عن آخر شمعة معاكسة قبل الحركة", "حدد قمة وقاع تلك الشمعة كمنطقة OB", "انتظر عودة السعر لهذه المنطقة", "ادخل عندما يُظهر السعر رفضاً عند OB"], example: "السعر يهبط بقوة من 1.1000. آخر شمعة خضراء قبل الهبوط كانت عند 1.0990-1.1000. عند عودة السعر لهذه المنطقة، يُرفض ويهبط مجدداً.", keyTakeaways: ["OB = آخر شمعة قبل حركة اندفاعية", "OB صعودي = آخر شمعة حمراء قبل الصعود", "OB هبوطي = آخر شمعة خضراء قبل الهبوط", "السعر غالباً يتفاعل عند كتل الأوامر"] }, fr: { title: "Order Blocks", content: "Un Order Block est la dernière bougie avant un mouvement impulsif. C'est là où les institutions ont placé leurs ordres.", steps: ["Identifiez un mouvement impulsif", "Trouvez la dernière bougie opposée", "Marquez la zone OB", "Attendez le retour du prix", "Entrez au rejet"], example: "Le prix chute de 1.1000. La dernière bougie verte avant = OB baissier.", keyTakeaways: ["OB = dernière bougie avant l'impulsion", "OB haussier = dernière rouge", "OB baissier = dernière verte", "Le prix réagit aux OB"] }, es: { title: "Order Blocks", content: "Un Order Block es la última vela antes de un movimiento impulsivo. Es donde las instituciones colocaron sus órdenes.", steps: ["Identifica un movimiento impulsivo", "Encuentra la última vela opuesta", "Marca la zona OB", "Espera el retorno del precio", "Entra en el rechazo"], example: "El precio cae de 1.1000. La última vela verde antes = OB bajista.", keyTakeaways: ["OB = última vela antes del impulso", "OB alcista = última roja", "OB bajista = última verde", "El precio reacciona en OB"] } },
  { id: 5, diagram: 'fvg', en: { title: "Fair Value Gap (FVG)", content: "A Fair Value Gap (FVG) is an imbalance in price created by a strong impulsive move. It appears as a gap between three consecutive candles where the wicks of candle 1 and candle 3 don't overlap.\n\nFVGs represent areas where price moved too fast, leaving unfilled orders. Price tends to return to fill these gaps before continuing.\n\n**Bullish FVG:** Gap created during an upward move. Price may pull back to fill it before continuing up.\n**Bearish FVG:** Gap created during a downward move. Price may pull back to fill it before continuing down.", steps: ["Look for three consecutive candles with a strong move", "Check if candle 1's high and candle 3's low don't overlap (bullish FVG)", "Or if candle 1's low and candle 3's high don't overlap (bearish FVG)", "Mark the gap zone on your chart", "Wait for price to return to the FVG for entry"], example: "Three bullish candles: Candle 1 high at 1.0980, Candle 3 low at 1.0990. There's a gap between 1.0980 and 1.0990. Price may pull back to this zone before continuing up.", keyTakeaways: ["FVG = imbalance between 3 candles", "Price tends to fill FVGs before continuing", "Bullish FVG = entry for longs", "Bearish FVG = entry for shorts"] }, ar: { title: "فجوة القيمة العادلة (FVG)", content: "فجوة القيمة العادلة هي عدم توازن في السعر ناتج عن حركة اندفاعية قوية. تظهر كفجوة بين ثلاث شموع متتالية.\n\nتمثل FVG مناطق تحرك فيها السعر بسرعة كبيرة تاركاً أوامر غير منفذة. السعر يميل للعودة لملء هذه الفجوات.", steps: ["ابحث عن ثلاث شموع متتالية بحركة قوية", "تحقق من عدم تداخل ذيول الشمعة 1 و3", "حدد منطقة الفجوة", "انتظر عودة السعر للفجوة", "ادخل عند الفجوة"], example: "ثلاث شموع صعودية: قمة الشمعة 1 عند 1.0980، قاع الشمعة 3 عند 1.0990. الفجوة بين 1.0980 و1.0990.", keyTakeaways: ["FVG = عدم توازن بين 3 شموع", "السعر يميل لملء الفجوات", "FVG صعودي = دخول شراء", "FVG هبوطي = دخول بيع"] }, fr: { title: "Fair Value Gap (FVG)", content: "Un FVG est un déséquilibre de prix créé par un mouvement impulsif entre 3 bougies.", steps: ["Cherchez 3 bougies consécutives", "Vérifiez le gap", "Marquez la zone", "Attendez le retour", "Entrez au FVG"], example: "Gap entre 1.0980 et 1.0990 dans un mouvement haussier.", keyTakeaways: ["FVG = déséquilibre", "Le prix remplit les FVG", "FVG haussier = achat", "FVG baissier = vente"] }, es: { title: "Fair Value Gap (FVG)", content: "Un FVG es un desequilibrio de precio creado por un movimiento impulsivo entre 3 velas.", steps: ["Busca 3 velas consecutivas", "Verifica el gap", "Marca la zona", "Espera el retorno", "Entra en el FVG"], example: "Gap entre 1.0980 y 1.0990 en movimiento alcista.", keyTakeaways: ["FVG = desequilibrio", "El precio llena los FVG", "FVG alcista = compra", "FVG bajista = venta"] } },
  { id: 6, diagram: 'bos', en: { title: "Break of Structure (BOS)", content: "A Break of Structure occurs when price breaks a significant swing point, confirming the continuation of the current trend.\n\n**Bullish BOS:** Price breaks above a previous swing high, confirming the uptrend.\n**Bearish BOS:** Price breaks below a previous swing low, confirming the downtrend.\n\nBOS is your confirmation that the trend is still intact and you should look for entries in that direction.", steps: ["Identify the current market structure", "Mark the most recent swing high and swing low", "Wait for price to break the swing high (bullish BOS) or swing low (bearish BOS)", "After BOS, look for entry opportunities on pullbacks", "Use order blocks or FVGs as entry points after BOS"], example: "In an uptrend, the last swing high is at 1.1050. When price closes above 1.1050, that's a bullish BOS. Now wait for a pullback to an order block or FVG to enter long.", keyTakeaways: ["BOS confirms trend continuation", "Bullish BOS = break above swing high", "Bearish BOS = break below swing low", "Enter on pullbacks after BOS"] }, ar: { title: "كسر الهيكل (BOS)", content: "كسر الهيكل يحدث عندما يكسر السعر نقطة تأرجح مهمة، مؤكداً استمرار الاتجاه الحالي.\n\n**BOS صعودي:** السعر يكسر فوق قمة سابقة.\n**BOS هبوطي:** السعر يكسر تحت قاع سابق.", steps: ["حدد هيكل السوق الحالي", "حدد آخر قمة وقاع متأرجحين", "انتظر كسر القمة (BOS صعودي) أو القاع (BOS هبوطي)", "بعد BOS، ابحث عن فرص دخول عند التراجعات", "استخدم OB أو FVG كنقاط دخول بعد BOS"], example: "في اتجاه صاعد، آخر قمة عند 1.1050. عندما يغلق السعر فوق 1.1050، هذا BOS صعودي. انتظر تراجعاً لـ OB أو FVG للدخول.", keyTakeaways: ["BOS يؤكد استمرار الاتجاه", "BOS صعودي = كسر فوق القمة", "BOS هبوطي = كسر تحت القاع", "ادخل عند التراجعات بعد BOS"] }, fr: { title: "Break of Structure (BOS)", content: "Un BOS confirme la continuation de la tendance quand le prix casse un swing point.", steps: ["Identifiez la structure", "Marquez les swings", "Attendez la cassure", "Cherchez des entrées", "Utilisez OB/FVG"], example: "Cassure au-dessus de 1.1050 = BOS haussier.", keyTakeaways: ["BOS = continuation", "Haussier = cassure du haut", "Baissier = cassure du bas", "Entrez sur pullback"] }, es: { title: "Break of Structure (BOS)", content: "Un BOS confirma la continuación de tendencia cuando el precio rompe un swing point.", steps: ["Identifica la estructura", "Marca los swings", "Espera la ruptura", "Busca entradas", "Usa OB/FVG"], example: "Ruptura arriba de 1.1050 = BOS alcista.", keyTakeaways: ["BOS = continuación", "Alcista = ruptura del máximo", "Bajista = ruptura del mínimo", "Entra en pullback"] } },
  { id: 7, diagram: 'market-structure', en: { title: "Change of Character (CHoCH)", content: "A Change of Character is the first sign that the market structure is shifting. It occurs when price breaks a key level in the opposite direction of the current trend.\n\nIn an uptrend, a CHoCH happens when price breaks below the most recent higher low.\nIn a downtrend, a CHoCH happens when price breaks above the most recent lower high.\n\nCHoCH is an early warning signal — it doesn't guarantee a reversal, but it tells you to be cautious.", steps: ["Monitor the current trend structure", "Watch for price to break a key swing point against the trend", "Mark the CHoCH level on your chart", "Wait for confirmation (BOS in the new direction)", "Look for entries using OB/FVG after confirmation"], example: "Uptrend with HL at 1.1000. Price suddenly drops below 1.1000 — this is a CHoCH. If price then makes a lower high and breaks below the next low, the reversal is confirmed.", keyTakeaways: ["CHoCH = first sign of structure shift", "Doesn't guarantee reversal alone", "Wait for confirmation before trading", "Use as an early warning signal"] }, ar: { title: "تغيير الطابع (CHoCH)", content: "تغيير الطابع هو أول علامة على تحول هيكل السوق. يحدث عندما يكسر السعر مستوى رئيسي في الاتجاه المعاكس.\n\nفي اتجاه صاعد، CHoCH يحدث عندما يكسر السعر تحت آخر قاع أعلى.\nفي اتجاه هابط، CHoCH يحدث عندما يكسر السعر فوق آخر قمة أدنى.", steps: ["راقب هيكل الاتجاه الحالي", "انتبه لكسر السعر نقطة تأرجح ضد الاتجاه", "حدد مستوى CHoCH", "انتظر التأكيد (BOS في الاتجاه الجديد)", "ابحث عن دخول بعد التأكيد"], example: "اتجاه صاعد مع HL عند 1.1000. السعر يهبط فجأة تحت 1.1000 — هذا CHoCH. إذا صنع السعر قمة أدنى وكسر القاع التالي، الانعكاس مؤكد.", keyTakeaways: ["CHoCH = أول علامة على تحول الهيكل", "لا يضمن الانعكاس وحده", "انتظر التأكيد قبل التداول", "استخدمه كإنذار مبكر"] }, fr: { title: "Change of Character (CHoCH)", content: "Un CHoCH est le premier signe de changement de structure du marché.", steps: ["Surveillez la structure", "Observez les cassures contre-tendance", "Marquez le CHoCH", "Attendez la confirmation", "Entrez après confirmation"], example: "HL à 1.1000 cassé = CHoCH dans une tendance haussière.", keyTakeaways: ["CHoCH = premier signe", "Pas de garantie seul", "Attendez confirmation", "Signal d'alerte"] }, es: { title: "Change of Character (CHoCH)", content: "Un CHoCH es la primera señal de cambio de estructura del mercado.", steps: ["Monitorea la estructura", "Observa rupturas contra-tendencia", "Marca el CHoCH", "Espera confirmación", "Entra después de confirmar"], example: "HL en 1.1000 roto = CHoCH en tendencia alcista.", keyTakeaways: ["CHoCH = primera señal", "No garantiza solo", "Espera confirmación", "Señal de alerta"] } },
  { id: 8, diagram: 'liquidity', en: { title: "Liquidity Sweeps", content: "A liquidity sweep occurs when price briefly moves beyond a key level to trigger stop losses, then quickly reverses. This is the smart money collecting liquidity.\n\nSweeps are powerful trading signals because they show you exactly where institutions are active.", steps: ["Identify key levels with obvious liquidity", "Wait for price to sweep beyond the level", "Look for immediate rejection (long wicks)", "Enter in the reversal direction", "Place stop loss beyond the sweep"], example: "Support at 1.0800 with equal lows. Price dips to 1.0790, creates a long wick, and closes back above 1.0800. Enter long at 1.0810 with SL at 1.0785.", keyTakeaways: ["Sweeps = smart money collecting liquidity", "Look for long wicks at key levels", "Enter after the sweep reverses", "Very high probability setups"] }, ar: { title: "اكتساح السيولة", content: "اكتساح السيولة يحدث عندما يتحرك السعر لفترة وجيزة وراء مستوى رئيسي لتفعيل أوامر وقف الخسارة ثم ينعكس بسرعة. هذا المال الذكي يجمع السيولة.", steps: ["حدد المستويات الرئيسية ذات السيولة الواضحة", "انتظر اكتساح السعر وراء المستوى", "ابحث عن رفض فوري (ذيول طويلة)", "ادخل في اتجاه الانعكاس", "ضع وقف الخسارة وراء الاكتساح"], example: "دعم عند 1.0800 مع قيعان متساوية. السعر يهبط إلى 1.0790 ويغلق فوق 1.0800. ادخل شراء عند 1.0810.", keyTakeaways: ["الاكتساح = المال الذكي يجمع السيولة", "ابحث عن ذيول طويلة عند المستويات", "ادخل بعد انعكاس الاكتساح", "فرص عالية الاحتمالية"] }, fr: { title: "Sweeps de Liquidité", content: "Un sweep se produit quand le prix dépasse brièvement un niveau clé pour déclencher les stops puis revient.", steps: ["Identifiez les niveaux clés", "Attendez le sweep", "Cherchez le rejet", "Entrez en retournement", "SL au-delà du sweep"], example: "Support à 1.0800 sweepé à 1.0790 puis retour. Achat à 1.0810.", keyTakeaways: ["Sweep = collecte de liquidité", "Longues mèches", "Entrez après le retournement", "Haute probabilité"] }, es: { title: "Sweeps de Liquidez", content: "Un sweep ocurre cuando el precio supera brevemente un nivel clave para activar stops y luego regresa.", steps: ["Identifica niveles clave", "Espera el sweep", "Busca el rechazo", "Entra en reversión", "SL más allá del sweep"], example: "Soporte en 1.0800 sweepado a 1.0790 y regreso. Compra en 1.0810.", keyTakeaways: ["Sweep = colección de liquidez", "Mechas largas", "Entra después de la reversión", "Alta probabilidad"] } },
  { id: 9, diagram: 'entry-model', en: { title: "SMC Entry Models", content: "Now let's combine all SMC concepts into practical entry models:\n\n**Model 1: BOS + OB Entry**\n1. Identify BOS in your direction\n2. Wait for pullback to the order block\n3. Enter at the OB with SL below/above it\n\n**Model 2: Liquidity Sweep + FVG**\n1. Wait for liquidity sweep at a key level\n2. Look for FVG formation after the sweep\n3. Enter at the FVG with tight stop loss\n\n**Model 3: CHoCH + OB**\n1. Identify CHoCH for reversal\n2. Wait for BOS confirmation\n3. Enter at the OB that caused the CHoCH", steps: ["Choose the model that fits the current market condition", "Always wait for all conditions to be met", "Use higher timeframe for bias, lower for entry", "Risk 1-2% per trade", "Target previous liquidity levels for take profit"], example: "H4 shows bullish BOS. M15 shows pullback to a bullish OB at 1.0850 with FVG. Enter long at 1.0855, SL at 1.0835, TP at 1.0920 (previous BSL).", keyTakeaways: ["Multiple entry models for different scenarios", "Always wait for all conditions", "Higher TF for bias, lower TF for entry", "Target liquidity levels for TP"] }, ar: { title: "نماذج دخول SMC", content: "لنجمع مفاهيم SMC في نماذج دخول عملية:\n\n**النموذج 1: BOS + OB**\n1. حدد BOS في اتجاهك\n2. انتظر تراجعاً لكتلة الأوامر\n3. ادخل عند OB\n\n**النموذج 2: اكتساح سيولة + FVG**\n**النموذج 3: CHoCH + OB**", steps: ["اختر النموذج المناسب للسوق الحالي", "انتظر دائماً تحقق جميع الشروط", "إطار أعلى للاتجاه، أدنى للدخول", "خاطر بـ 1-2% لكل صفقة", "استهدف مستويات السيولة السابقة"], example: "H4 يُظهر BOS صعودي. M15 يُظهر تراجعاً لـ OB صعودي عند 1.0850. ادخل شراء عند 1.0855، وقف 1.0835، هدف 1.0920.", keyTakeaways: ["نماذج دخول متعددة لسيناريوهات مختلفة", "انتظر دائماً تحقق جميع الشروط", "إطار أعلى للاتجاه، أدنى للدخول", "استهدف مستويات السيولة"] }, fr: { title: "Modèles d'Entrée SMC", content: "Combinons les concepts SMC en modèles pratiques: BOS+OB, Sweep+FVG, CHoCH+OB.", steps: ["Choisissez le modèle", "Attendez toutes les conditions", "TF supérieur pour le biais", "Risque 1-2%", "Ciblez la liquidité"], example: "BOS haussier H4 + pullback OB M15 à 1.0850.", keyTakeaways: ["Plusieurs modèles", "Toutes les conditions", "Multi-timeframe", "Ciblez la liquidité"] }, es: { title: "Modelos de Entrada SMC", content: "Combinemos conceptos SMC en modelos prácticos: BOS+OB, Sweep+FVG, CHoCH+OB.", steps: ["Elige el modelo", "Espera todas las condiciones", "TF superior para sesgo", "Riesgo 1-2%", "Apunta a la liquidez"], example: "BOS alcista H4 + pullback OB M15 en 1.0850.", keyTakeaways: ["Varios modelos", "Todas las condiciones", "Multi-timeframe", "Apunta a la liquidez"] } },
  { id: 10, diagram: 'risk-management', en: { title: "SMC Risk Management", content: "Risk management in SMC trading follows the same principles but with specific placement rules:\n\n**Stop Loss Placement:**\n- Below/above the order block\n- Beyond the liquidity sweep\n- Below/above the FVG\n\n**Take Profit Targets:**\n- Previous liquidity levels (BSL/SSL)\n- Opposing order blocks\n- Imbalances (FVGs) on higher timeframes", steps: ["Place SL beyond the invalidation point", "Target the nearest liquidity pool", "Use 1:2 minimum risk-to-reward", "Move SL to breakeven after 1:1", "Partial close at key levels"], example: "Enter long at OB 1.0850. SL below OB at 1.0830 (20 pips). TP1 at 1.0890 (1:2), TP2 at 1.0930 (1:4). Move SL to breakeven after TP1.", keyTakeaways: ["SL beyond invalidation point", "TP at liquidity levels", "Minimum 1:2 RR", "Partial closes for safety"] }, ar: { title: "إدارة المخاطر في SMC", content: "إدارة المخاطر في تداول SMC تتبع نفس المبادئ مع قواعد وضع محددة:\n\n**وضع وقف الخسارة:**\n- تحت/فوق كتلة الأوامر\n- وراء اكتساح السيولة\n- تحت/فوق FVG\n\n**أهداف جني الأرباح:**\n- مستويات السيولة السابقة\n- كتل أوامر معاكسة", steps: ["ضع SL وراء نقطة الإبطال", "استهدف أقرب تجمع سيولة", "استخدم 1:2 كحد أدنى", "حرك SL للتعادل بعد 1:1", "إغلاق جزئي عند مستويات رئيسية"], example: "دخول شراء عند OB 1.0850. SL تحت OB عند 1.0830. TP1 عند 1.0890 (1:2)، TP2 عند 1.0930 (1:4).", keyTakeaways: ["SL وراء نقطة الإبطال", "TP عند مستويات السيولة", "حد أدنى 1:2 RR", "إغلاقات جزئية للأمان"] }, fr: { title: "Gestion des Risques SMC", content: "Gestion du risque SMC: SL au-delà de l'invalidation, TP aux niveaux de liquidité.", steps: ["SL au-delà de l'invalidation", "Ciblez la liquidité", "Minimum 1:2 RR", "SL au breakeven après 1:1", "Clôtures partielles"], example: "Achat à OB 1.0850, SL 1.0830, TP1 1.0890, TP2 1.0930.", keyTakeaways: ["SL au-delà de l'invalidation", "TP à la liquidité", "Minimum 1:2", "Clôtures partielles"] }, es: { title: "Gestión de Riesgos SMC", content: "Gestión de riesgo SMC: SL más allá de invalidación, TP en niveles de liquidez.", steps: ["SL más allá de invalidación", "Apunta a la liquidez", "Mínimo 1:2 RR", "SL a breakeven después de 1:1", "Cierres parciales"], example: "Compra en OB 1.0850, SL 1.0830, TP1 1.0890, TP2 1.0930.", keyTakeaways: ["SL más allá de invalidación", "TP en liquidez", "Mínimo 1:2", "Cierres parciales"] } },
  { id: 11, diagram: 'entry-model', en: { title: "Premium & Discount Zones", content: "The market always moves between premium and discount zones relative to the current range.\n\n**Discount Zone:** Below the 50% level of the range — this is where smart money buys.\n**Premium Zone:** Above the 50% level of the range — this is where smart money sells.\n\nAlways buy in the discount zone and sell in the premium zone for optimal entries.", steps: ["Identify the current trading range (swing high to swing low)", "Draw the 50% level (equilibrium)", "Mark the discount zone (below 50%)", "Mark the premium zone (above 50%)", "Only buy in discount, only sell in premium"], example: "Range from 1.0800 (low) to 1.1000 (high). The 50% is 1.0900. Buy setups below 1.0900 (discount), sell setups above 1.0900 (premium).", keyTakeaways: ["Buy in discount (below 50%)", "Sell in premium (above 50%)", "This improves your risk-to-reward significantly", "Combine with OB and FVG for best entries"] }, ar: { title: "مناطق العلاوة والخصم", content: "السوق يتحرك دائماً بين مناطق العلاوة والخصم.\n\n**منطقة الخصم:** تحت مستوى 50% — حيث يشتري المال الذكي.\n**منطقة العلاوة:** فوق مستوى 50% — حيث يبيع المال الذكي.", steps: ["حدد النطاق الحالي", "ارسم مستوى 50% (التوازن)", "حدد منطقة الخصم (تحت 50%)", "حدد منطقة العلاوة (فوق 50%)", "اشترِ فقط في الخصم، بِع فقط في العلاوة"], example: "نطاق من 1.0800 إلى 1.1000. مستوى 50% عند 1.0900. اشترِ تحت 1.0900، بِع فوق 1.0900.", keyTakeaways: ["اشترِ في الخصم (تحت 50%)", "بِع في العلاوة (فوق 50%)", "يحسن نسبة المخاطرة/المكافأة", "ادمج مع OB و FVG"] }, fr: { title: "Zones Premium & Discount", content: "Le marché se déplace entre zones premium et discount. Achetez en discount, vendez en premium.", steps: ["Identifiez le range", "Tracez le 50%", "Marquez discount", "Marquez premium", "Achetez en discount, vendez en premium"], example: "Range 1.0800-1.1000. 50% = 1.0900. Achetez sous 1.0900.", keyTakeaways: ["Achetez en discount", "Vendez en premium", "Meilleur RR", "Combinez avec OB/FVG"] }, es: { title: "Zonas Premium & Discount", content: "El mercado se mueve entre zonas premium y discount. Compra en discount, vende en premium.", steps: ["Identifica el rango", "Traza el 50%", "Marca discount", "Marca premium", "Compra en discount, vende en premium"], example: "Rango 1.0800-1.1000. 50% = 1.0900. Compra bajo 1.0900.", keyTakeaways: ["Compra en discount", "Vende en premium", "Mejor RR", "Combina con OB/FVG"] } },
  { id: 12, diagram: 'entry-model', en: { title: "SMC Complete Strategy", content: "Let's put the complete SMC strategy together:\n\n1. **Higher TF Analysis:** Identify the trend and key levels on Daily/H4\n2. **Mark Liquidity:** Find BSL and SSL on the higher timeframe\n3. **Wait for Sweep:** Let smart money grab liquidity\n4. **Look for CHoCH/BOS:** Confirm the direction on lower TF\n5. **Find Entry:** Use OB or FVG on M15/M5\n6. **Manage Risk:** SL beyond invalidation, TP at liquidity", steps: ["Analyze Daily chart for overall bias", "Mark liquidity pools on H4", "Switch to M15 when price reaches key area", "Wait for liquidity sweep + structure shift", "Enter at OB/FVG with proper risk management", "Target opposing liquidity for take profit"], example: "Daily: Bullish trend. H4: Price approaching SSL at 1.0800. M15: Price sweeps 1.0800, CHoCH forms, bullish BOS confirms. Enter at bullish OB 1.0815, SL 1.0795, TP 1.0900 (BSL). Risk: 20 pips, Reward: 85 pips = 1:4.25 RR.", keyTakeaways: ["Multi-timeframe analysis is essential", "Always wait for liquidity sweep first", "Confirm with structure shift (CHoCH/BOS)", "Enter at OB/FVG for precision", "Target opposing liquidity for TP"] }, ar: { title: "استراتيجية SMC الكاملة", content: "لنجمع استراتيجية SMC الكاملة:\n\n1. **تحليل الإطار الأعلى:** حدد الاتجاه على اليومي/H4\n2. **حدد السيولة:** ابحث عن BSL و SSL\n3. **انتظر الاكتساح:** دع المال الذكي يجمع السيولة\n4. **ابحث عن CHoCH/BOS:** أكد الاتجاه على إطار أدنى\n5. **ابحث عن الدخول:** استخدم OB أو FVG\n6. **أدر المخاطر:** SL وراء الإبطال، TP عند السيولة", steps: ["حلل الرسم اليومي للاتجاه العام", "حدد تجمعات السيولة على H4", "انتقل إلى M15 عند وصول السعر لمنطقة رئيسية", "انتظر اكتساح السيولة + تحول الهيكل", "ادخل عند OB/FVG بإدارة مخاطر سليمة", "استهدف السيولة المعاكسة لجني الأرباح"], example: "يومي: اتجاه صاعد. H4: السعر يقترب من SSL عند 1.0800. M15: السعر يكتسح 1.0800، CHoCH يتشكل، BOS صعودي يؤكد. دخول عند OB 1.0815، SL 1.0795، TP 1.0900. نسبة 1:4.25.", keyTakeaways: ["تحليل متعدد الأطر ضروري", "انتظر اكتساح السيولة أولاً", "أكد بتحول الهيكل", "ادخل عند OB/FVG للدقة", "استهدف السيولة المعاكسة"] }, fr: { title: "Stratégie SMC Complète", content: "Stratégie complète: analyse multi-TF, liquidité, sweep, structure, entrée OB/FVG.", steps: ["Analysez le Daily", "Marquez la liquidité H4", "Passez au M15", "Attendez sweep + structure", "Entrez à OB/FVG", "Ciblez la liquidité opposée"], example: "Daily haussier. H4 SSL à 1.0800. M15 sweep + CHoCH + BOS. Achat OB 1.0815.", keyTakeaways: ["Multi-TF essentiel", "Attendez le sweep", "Confirmez la structure", "Entrez à OB/FVG", "Ciblez la liquidité"] }, es: { title: "Estrategia SMC Completa", content: "Estrategia completa: análisis multi-TF, liquidez, sweep, estructura, entrada OB/FVG.", steps: ["Analiza el Daily", "Marca liquidez H4", "Cambia a M15", "Espera sweep + estructura", "Entra en OB/FVG", "Apunta liquidez opuesta"], example: "Daily alcista. H4 SSL en 1.0800. M15 sweep + CHoCH + BOS. Compra OB 1.0815.", keyTakeaways: ["Multi-TF esencial", "Espera el sweep", "Confirma estructura", "Entra en OB/FVG", "Apunta liquidez"] } }
];

export const ictLessons = [
  { id: 1, diagram: 'market-structure', en: { title: "Introduction to ICT Trading", content: "ICT (Inner Circle Trader) is a trading methodology developed by Michael J. Huddleston. It focuses on understanding institutional order flow and how banks manipulate the market.\n\nICT builds on similar concepts to SMC but adds unique elements like Kill Zones, Optimal Trade Entry (OTE), and specific time-based analysis.", steps: ["Understand that ICT focuses on institutional behavior", "Learn the key time zones when institutions are active", "Study how price delivers to liquidity", "Master the concept of displacement", "Practice on demo before going live"], example: "ICT traders focus on specific times like London Open (2-5 AM EST) and NY Open (7-10 AM EST) because these are when institutions are most active.", keyTakeaways: ["ICT = institutional order flow methodology", "Time-based analysis is crucial", "Focus on when institutions trade", "Combines structure, liquidity, and time"] }, ar: { title: "مقدمة في تداول ICT", content: "ICT (المتداول الداخلي) هي منهجية تداول طورها مايكل هادلستون. تركز على فهم تدفق الأوامر المؤسسية وكيف تتلاعب البنوك بالسوق.\n\nICT تبني على مفاهيم مشابهة لـ SMC لكن تضيف عناصر فريدة مثل مناطق القتل والدخول الأمثل.", steps: ["افهم أن ICT تركز على السلوك المؤسسي", "تعلم المناطق الزمنية الرئيسية", "ادرس كيف يتوجه السعر للسيولة", "أتقن مفهوم الإزاحة", "تدرب على حساب تجريبي"], example: "متداولو ICT يركزون على أوقات محددة مثل افتتاح لندن وافتتاح نيويورك لأن المؤسسات تكون أكثر نشاطاً.", keyTakeaways: ["ICT = منهجية تدفق الأوامر المؤسسية", "التحليل الزمني حاسم", "ركز على وقت تداول المؤسسات", "يجمع الهيكل والسيولة والوقت"] }, fr: { title: "Introduction au Trading ICT", content: "ICT est une méthodologie focalisée sur le flux d'ordres institutionnel et la manipulation bancaire.", steps: ["Comprenez le comportement institutionnel", "Apprenez les zones temporelles", "Étudiez la livraison du prix", "Maîtrisez le déplacement", "Pratiquez en démo"], example: "Les traders ICT se concentrent sur l'ouverture de Londres et NY.", keyTakeaways: ["ICT = flux institutionnel", "Analyse temporelle cruciale", "Focus sur les institutions", "Structure + liquidité + temps"] }, es: { title: "Introducción al Trading ICT", content: "ICT es una metodología enfocada en el flujo de órdenes institucional y la manipulación bancaria.", steps: ["Entiende el comportamiento institucional", "Aprende las zonas temporales", "Estudia la entrega del precio", "Domina el desplazamiento", "Practica en demo"], example: "Los traders ICT se enfocan en la apertura de Londres y NY.", keyTakeaways: ["ICT = flujo institucional", "Análisis temporal crucial", "Enfoque en instituciones", "Estructura + liquidez + tiempo"] } },
  { id: 2, diagram: 'market-structure', en: { title: "ICT Market Structure", content: "ICT market structure follows the same principles of swing highs and lows but with specific terminology:\n\n**Swing High:** A candle with lower highs on both sides\n**Swing Low:** A candle with higher lows on both sides\n**Internal Structure:** Minor swings within the larger structure\n**External Structure:** Major swings that define the overall trend\n\nICT emphasizes the difference between internal and external structure for multi-timeframe analysis.", steps: ["Identify external structure on higher timeframes", "Mark internal structure on lower timeframes", "Understand the relationship between the two", "Use external for bias, internal for entries", "Practice marking structure on multiple pairs"], example: "On H4, the external structure shows HH and HL (bullish). On M15, the internal structure shows a pullback with LH and LL. When M15 structure shifts back to bullish, it's an entry opportunity.", keyTakeaways: ["External structure = overall trend", "Internal structure = minor moves within trend", "Use both for complete analysis", "External for bias, internal for entry"] }, ar: { title: "هيكل السوق في ICT", content: "هيكل السوق في ICT يتبع نفس مبادئ القمم والقيعان مع مصطلحات محددة:\n\n**الهيكل الخارجي:** التأرجحات الرئيسية التي تحدد الاتجاه العام\n**الهيكل الداخلي:** التأرجحات الفرعية داخل الهيكل الأكبر", steps: ["حدد الهيكل الخارجي على الأطر الأعلى", "حدد الهيكل الداخلي على الأطر الأدنى", "افهم العلاقة بينهما", "استخدم الخارجي للاتجاه، الداخلي للدخول", "تدرب على تحديد الهيكل"], example: "على H4، الهيكل الخارجي صعودي. على M15، الهيكل الداخلي يُظهر تراجعاً. عندما يعود M15 للصعود، فهذه فرصة دخول.", keyTakeaways: ["الهيكل الخارجي = الاتجاه العام", "الهيكل الداخلي = حركات فرعية", "استخدم كليهما للتحليل الكامل", "الخارجي للاتجاه، الداخلي للدخول"] }, fr: { title: "Structure du Marché ICT", content: "Structure ICT: externe pour la tendance, interne pour les mouvements mineurs.", steps: ["Identifiez la structure externe", "Marquez la structure interne", "Comprenez la relation", "Externe pour le biais", "Interne pour l'entrée"], example: "H4 haussier (externe), M15 pullback (interne). Entrée quand M15 redevient haussier.", keyTakeaways: ["Externe = tendance", "Interne = mouvements mineurs", "Les deux pour l'analyse", "Externe = biais, Interne = entrée"] }, es: { title: "Estructura del Mercado ICT", content: "Estructura ICT: externa para tendencia, interna para movimientos menores.", steps: ["Identifica estructura externa", "Marca estructura interna", "Entiende la relación", "Externa para sesgo", "Interna para entrada"], example: "H4 alcista (externa), M15 pullback (interna). Entrada cuando M15 vuelve alcista.", keyTakeaways: ["Externa = tendencia", "Interna = movimientos menores", "Ambas para análisis", "Externa = sesgo, Interna = entrada"] } },
  { id: 3, diagram: 'liquidity', en: { title: "ICT Liquidity Concepts", content: "ICT defines liquidity as resting orders at key price levels. Understanding where liquidity sits is the key to predicting where price will go next.\n\n**Buy Stops (BSL):** Above swing highs, above equal highs, above trendlines\n**Sell Stops (SSL):** Below swing lows, below equal lows, below trendlines\n\nPrice is always seeking liquidity. It moves from one pool of liquidity to another.", steps: ["Mark all obvious swing highs and lows", "Identify equal highs and equal lows", "Understand that price targets these levels", "Wait for price to reach a liquidity level", "Look for reversal signals after liquidity is taken"], example: "Three equal highs at 1.1000 create a pool of buy stops. Price will likely run above 1.1000 to grab those stops before potentially reversing.", keyTakeaways: ["Price always seeks liquidity", "BSL above highs, SSL below lows", "Equal highs/lows = strong liquidity pools", "Price moves from one pool to another"] }, ar: { title: "مفاهيم السيولة في ICT", content: "ICT تعرف السيولة كأوامر معلقة عند مستويات سعرية رئيسية.\n\n**أوامر الشراء المعلقة (BSL):** فوق القمم\n**أوامر البيع المعلقة (SSL):** تحت القيعان\n\nالسعر يبحث دائماً عن السيولة.", steps: ["حدد جميع القمم والقيعان الواضحة", "حدد القمم والقيعان المتساوية", "افهم أن السعر يستهدف هذه المستويات", "انتظر وصول السعر لمستوى سيولة", "ابحث عن إشارات انعكاس بعد أخذ السيولة"], example: "ثلاث قمم متساوية عند 1.1000 تخلق تجمع سيولة. السعر سيرتفع فوق 1.1000 لأخذ تلك الأوامر.", keyTakeaways: ["السعر يبحث دائماً عن السيولة", "BSL فوق القمم، SSL تحت القيعان", "القمم/القيعان المتساوية = تجمعات سيولة قوية", "السعر يتحرك من تجمع لآخر"] }, fr: { title: "Liquidité ICT", content: "ICT définit la liquidité comme des ordres en attente aux niveaux clés. Le prix cherche toujours la liquidité.", steps: ["Marquez les swings", "Identifiez les equal highs/lows", "Le prix cible ces niveaux", "Attendez l'arrivée au niveau", "Cherchez le retournement"], example: "Trois equal highs à 1.1000 = pool de liquidité.", keyTakeaways: ["Le prix cherche la liquidité", "BSL/SSL", "Equal highs/lows = forte liquidité", "Prix va de pool en pool"] }, es: { title: "Liquidez ICT", content: "ICT define liquidez como órdenes pendientes en niveles clave. El precio siempre busca liquidez.", steps: ["Marca los swings", "Identifica equal highs/lows", "El precio apunta a estos niveles", "Espera la llegada al nivel", "Busca reversión"], example: "Tres equal highs en 1.1000 = pool de liquidez.", keyTakeaways: ["El precio busca liquidez", "BSL/SSL", "Equal highs/lows = fuerte liquidez", "Precio va de pool a pool"] } },
  { id: 4, diagram: 'kill-zones', en: { title: "Kill Zones", content: "Kill Zones are specific time windows when institutional traders are most active and the highest probability setups occur.\n\n**Asian Kill Zone:** 8:00 PM - 12:00 AM EST — Range formation, sets the high/low of the day\n**London Kill Zone:** 2:00 AM - 5:00 AM EST — Often reverses Asian range, high volatility\n**New York Kill Zone:** 7:00 AM - 10:00 AM EST — Highest volume, best setups\n**London Close:** 10:00 AM - 12:00 PM EST — Reversals and profit-taking\n\nTrading only during Kill Zones dramatically improves your win rate.", steps: ["Mark the Kill Zone times on your chart", "Identify the Asian range high and low", "Watch for London to sweep Asian liquidity", "Look for NY Kill Zone setups", "Avoid trading outside Kill Zones"], example: "Asian range: 1.0850-1.0880. London opens and sweeps below 1.0850, then reverses up. Enter long at 1.0855 with SL at 1.0840. This is a classic London Kill Zone setup.", keyTakeaways: ["Kill Zones = institutional activity windows", "Asian sets the range", "London often reverses Asian", "NY has the best setups", "Only trade during Kill Zones"] }, ar: { title: "مناطق القتل", content: "مناطق القتل هي نوافذ زمنية محددة عندما يكون المتداولون المؤسسيون أكثر نشاطاً.\n\n**منطقة آسيا:** 8:00 م - 12:00 ص EST — تشكيل النطاق\n**منطقة لندن:** 2:00 ص - 5:00 ص EST — غالباً تعكس نطاق آسيا\n**منطقة نيويورك:** 7:00 ص - 10:00 ص EST — أعلى حجم\n**إغلاق لندن:** 10:00 ص - 12:00 م EST — انعكاسات", steps: ["حدد أوقات مناطق القتل على الرسم", "حدد قمة وقاع النطاق الآسيوي", "راقب لندن لاكتساح سيولة آسيا", "ابحث عن فرص في منطقة نيويورك", "تجنب التداول خارج مناطق القتل"], example: "نطاق آسيا: 1.0850-1.0880. لندن تكتسح تحت 1.0850 ثم تنعكس صعوداً. ادخل شراء عند 1.0855.", keyTakeaways: ["مناطق القتل = نوافذ النشاط المؤسسي", "آسيا تحدد النطاق", "لندن غالباً تعكس آسيا", "نيويورك لديها أفضل الفرص", "تداول فقط في مناطق القتل"] }, fr: { title: "Kill Zones", content: "Les Kill Zones sont des fenêtres temporelles d'activité institutionnelle maximale.", steps: ["Marquez les Kill Zones", "Identifiez le range asiatique", "Observez Londres", "Cherchez les setups NY", "Évitez hors Kill Zones"], example: "Range asiatique 1.0850-1.0880. Londres sweep sous 1.0850 puis remonte.", keyTakeaways: ["Kill Zones = activité institutionnelle", "Asie = range", "Londres reverse l'Asie", "NY = meilleurs setups", "Tradez dans les Kill Zones"] }, es: { title: "Kill Zones", content: "Las Kill Zones son ventanas temporales de máxima actividad institucional.", steps: ["Marca las Kill Zones", "Identifica el rango asiático", "Observa Londres", "Busca setups en NY", "Evita fuera de Kill Zones"], example: "Rango asiático 1.0850-1.0880. Londres sweep bajo 1.0850 y sube.", keyTakeaways: ["Kill Zones = actividad institucional", "Asia = rango", "Londres reversa Asia", "NY = mejores setups", "Opera en Kill Zones"] } },
  { id: 5, diagram: 'fibonacci', en: { title: "Optimal Trade Entry (OTE)", content: "The Optimal Trade Entry (OTE) is an ICT concept that uses Fibonacci retracement to find the best entry point during a pullback.\n\nThe OTE zone is between the 62% and 79% Fibonacci retracement levels. This is where institutions typically re-enter the market.\n\nCombine OTE with an order block or FVG in this zone for a high-probability entry.", steps: ["Identify a clear impulse move (BOS)", "Apply Fibonacci from the swing low to swing high (bullish)", "Mark the OTE zone (62%-79% retracement)", "Look for an OB or FVG within the OTE zone", "Enter at the OB/FVG with SL below the swing low"], example: "Bullish BOS from 1.0800 to 1.0900. OTE zone is 1.0838-1.0821. A bullish OB sits at 1.0830. Enter long at 1.0835, SL at 1.0795, TP at 1.0950.", keyTakeaways: ["OTE = 62%-79% Fibonacci zone", "Best entry during pullbacks", "Combine with OB/FVG for precision", "Provides excellent risk-to-reward"] }, ar: { title: "الدخول الأمثل للصفقة (OTE)", content: "الدخول الأمثل (OTE) هو مفهوم ICT يستخدم تصحيح فيبوناتشي لإيجاد أفضل نقطة دخول.\n\nمنطقة OTE بين مستويات 62% و79% فيبوناتشي. هذا حيث تعيد المؤسسات الدخول عادةً.", steps: ["حدد حركة اندفاعية واضحة (BOS)", "طبق فيبوناتشي من القاع للقمة", "حدد منطقة OTE (62%-79%)", "ابحث عن OB أو FVG في منطقة OTE", "ادخل عند OB/FVG مع SL تحت القاع"], example: "BOS صعودي من 1.0800 إلى 1.0900. منطقة OTE عند 1.0838-1.0821. OB صعودي عند 1.0830. ادخل شراء عند 1.0835.", keyTakeaways: ["OTE = منطقة فيبوناتشي 62%-79%", "أفضل دخول أثناء التراجعات", "ادمج مع OB/FVG للدقة", "يوفر نسبة مخاطرة/مكافأة ممتازة"] }, fr: { title: "Optimal Trade Entry (OTE)", content: "L'OTE utilise Fibonacci (62%-79%) pour trouver le meilleur point d'entrée pendant un pullback.", steps: ["Identifiez un BOS", "Appliquez Fibonacci", "Marquez la zone OTE", "Cherchez OB/FVG", "Entrez avec SL serré"], example: "BOS haussier 1.0800-1.0900. OTE à 1.0838-1.0821. OB à 1.0830.", keyTakeaways: ["OTE = Fibonacci 62%-79%", "Meilleure entrée en pullback", "Combinez avec OB/FVG", "Excellent RR"] }, es: { title: "Optimal Trade Entry (OTE)", content: "El OTE usa Fibonacci (62%-79%) para encontrar el mejor punto de entrada durante un pullback.", steps: ["Identifica un BOS", "Aplica Fibonacci", "Marca la zona OTE", "Busca OB/FVG", "Entra con SL ajustado"], example: "BOS alcista 1.0800-1.0900. OTE en 1.0838-1.0821. OB en 1.0830.", keyTakeaways: ["OTE = Fibonacci 62%-79%", "Mejor entrada en pullback", "Combina con OB/FVG", "Excelente RR"] } },
  { id: 6, diagram: 'fvg', en: { title: "ICT Fair Value Gaps", content: "ICT uses Fair Value Gaps as key entry zones. In ICT terminology, these are also called 'imbalances' or 'inefficiencies'.\n\nICT adds the concept of 'consequent encroachment' — the 50% level of the FVG, which is often the most reactive point.", steps: ["Identify FVGs on your chart", "Mark the 50% level (consequent encroachment)", "Wait for price to return to the FVG", "Watch for reaction at the 50% level", "Enter with confirmation"], example: "Bullish FVG between 1.0850 and 1.0870. The 50% (CE) is at 1.0860. Price pulls back and reacts exactly at 1.0860, forming a bullish candle. Enter long.", keyTakeaways: ["FVGs are key ICT entry zones", "The 50% level (CE) is most reactive", "Price often fills FVGs before continuing", "Combine with Kill Zones for timing"] }, ar: { title: "فجوات القيمة العادلة في ICT", content: "ICT تستخدم فجوات القيمة العادلة كمناطق دخول رئيسية. يضيف ICT مفهوم 'الاختراق التبعي' — مستوى 50% من FVG.", steps: ["حدد FVG على الرسم", "حدد مستوى 50% (CE)", "انتظر عودة السعر للفجوة", "راقب التفاعل عند مستوى 50%", "ادخل مع التأكيد"], example: "FVG صعودي بين 1.0850 و1.0870. مستوى 50% عند 1.0860. السعر يتراجع ويتفاعل عند 1.0860.", keyTakeaways: ["FVG مناطق دخول رئيسية في ICT", "مستوى 50% (CE) الأكثر تفاعلاً", "السعر غالباً يملأ FVG", "ادمج مع مناطق القتل للتوقيت"] }, fr: { title: "Fair Value Gaps ICT", content: "ICT utilise les FVG comme zones d'entrée clés avec le concept de consequent encroachment (50%).", steps: ["Identifiez les FVG", "Marquez le 50%", "Attendez le retour", "Observez la réaction", "Entrez avec confirmation"], example: "FVG haussier 1.0850-1.0870. CE à 1.0860.", keyTakeaways: ["FVG = zones d'entrée ICT", "50% le plus réactif", "Le prix remplit les FVG", "Combinez avec Kill Zones"] }, es: { title: "Fair Value Gaps ICT", content: "ICT usa los FVG como zonas de entrada clave con el concepto de consequent encroachment (50%).", steps: ["Identifica los FVG", "Marca el 50%", "Espera el retorno", "Observa la reacción", "Entra con confirmación"], example: "FVG alcista 1.0850-1.0870. CE en 1.0860.", keyTakeaways: ["FVG = zonas de entrada ICT", "50% más reactivo", "El precio llena los FVG", "Combina con Kill Zones"] } },
  { id: 7, diagram: 'order-blocks', en: { title: "ICT Order Blocks & Breaker Blocks", content: "ICT distinguishes between regular Order Blocks and Breaker Blocks:\n\n**Order Block:** The last candle before an impulsive move (same as SMC).\n**Breaker Block:** A failed order block that gets broken through. It then acts as support/resistance in the opposite direction.\n\nBreaker blocks are powerful because they represent a shift in institutional positioning.", steps: ["Identify order blocks as usual", "When an OB fails (price breaks through it), mark it as a breaker", "The breaker now acts as S/R in the opposite direction", "Wait for price to return to the breaker", "Enter in the direction of the break"], example: "A bullish OB at 1.0850 gets broken to the downside. This OB becomes a bearish breaker block. When price returns to 1.0850 from below, it gets rejected — enter short.", keyTakeaways: ["Breaker = failed order block", "Acts as S/R in opposite direction", "Shows institutional position shift", "Very reliable entry zones"] }, ar: { title: "كتل الأوامر وكتل الكسر في ICT", content: "ICT يميز بين كتل الأوامر العادية وكتل الكسر:\n\n**كتلة الأوامر:** آخر شمعة قبل حركة اندفاعية.\n**كتلة الكسر:** كتلة أوامر فاشلة تم اختراقها. تعمل بعدها كدعم/مقاومة في الاتجاه المعاكس.", steps: ["حدد كتل الأوامر كالمعتاد", "عندما تفشل OB، حددها ككتلة كسر", "كتلة الكسر تعمل كدعم/مقاومة معاكسة", "انتظر عودة السعر لكتلة الكسر", "ادخل في اتجاه الكسر"], example: "OB صعودي عند 1.0850 يُكسر للأسفل. يصبح كتلة كسر هبوطية. عند عودة السعر لـ 1.0850 من الأسفل، يُرفض — ادخل بيع.", keyTakeaways: ["كتلة الكسر = كتلة أوامر فاشلة", "تعمل كدعم/مقاومة معاكسة", "تُظهر تحول المواقع المؤسسية", "مناطق دخول موثوقة جداً"] }, fr: { title: "Order Blocks & Breaker Blocks ICT", content: "ICT distingue entre Order Blocks réguliers et Breaker Blocks (OB échoués qui deviennent S/R opposé).", steps: ["Identifiez les OB", "Quand un OB échoue = breaker", "Le breaker agit en S/R opposé", "Attendez le retour du prix", "Entrez dans la direction de la cassure"], example: "OB haussier à 1.0850 cassé = breaker baissier. Rejet à 1.0850 = vente.", keyTakeaways: ["Breaker = OB échoué", "S/R opposé", "Shift institutionnel", "Zones fiables"] }, es: { title: "Order Blocks & Breaker Blocks ICT", content: "ICT distingue entre Order Blocks regulares y Breaker Blocks (OB fallidos que se convierten en S/R opuesto).", steps: ["Identifica los OB", "Cuando un OB falla = breaker", "El breaker actúa como S/R opuesto", "Espera el retorno del precio", "Entra en la dirección de la ruptura"], example: "OB alcista en 1.0850 roto = breaker bajista. Rechazo en 1.0850 = venta.", keyTakeaways: ["Breaker = OB fallido", "S/R opuesto", "Shift institucional", "Zonas confiables"] } },
  { id: 8, diagram: 'entry-model', en: { title: "ICT Power of Three (AMD)", content: "The Power of Three describes the three phases of institutional price delivery each day:\n\n**A - Accumulation:** Smart money builds positions (usually during Asian session)\n**M - Manipulation:** Price is pushed against the intended direction to grab liquidity\n**D - Distribution:** The real move happens in the intended direction\n\nThis pattern repeats daily and understanding it gives you a massive edge.", steps: ["Identify the accumulation phase (Asian range)", "Watch for manipulation (false breakout of Asian range)", "Enter during distribution (the real move)", "Use Kill Zones to time each phase", "Combine with OB/FVG for entry"], example: "Asian range: 1.0850-1.0870. London manipulation: price drops to 1.0840 (below Asian low). Distribution: price reverses and rallies to 1.0920. Enter long after the manipulation at 1.0855.", keyTakeaways: ["AMD = Accumulation, Manipulation, Distribution", "Accumulation = Asian session", "Manipulation = false breakout", "Distribution = the real move"] }, ar: { title: "قوة الثلاثة في ICT (AMD)", content: "قوة الثلاثة تصف المراحل الثلاث لتوصيل السعر المؤسسي يومياً:\n\n**A - التجميع:** المال الذكي يبني مراكز (عادةً جلسة آسيا)\n**M - التلاعب:** السعر يُدفع عكس الاتجاه المقصود لجمع السيولة\n**D - التوزيع:** الحركة الحقيقية تحدث في الاتجاه المقصود", steps: ["حدد مرحلة التجميع (نطاق آسيا)", "راقب التلاعب (اختراق كاذب لنطاق آسيا)", "ادخل أثناء التوزيع (الحركة الحقيقية)", "استخدم مناطق القتل لتوقيت كل مرحلة", "ادمج مع OB/FVG للدخول"], example: "نطاق آسيا: 1.0850-1.0870. تلاعب لندن: السعر يهبط لـ 1.0840. التوزيع: السعر ينعكس ويصعد لـ 1.0920.", keyTakeaways: ["AMD = تجميع، تلاعب، توزيع", "التجميع = جلسة آسيا", "التلاعب = اختراق كاذب", "التوزيع = الحركة الحقيقية"] }, fr: { title: "Power of Three ICT (AMD)", content: "AMD: Accumulation (Asie), Manipulation (faux breakout), Distribution (le vrai mouvement).", steps: ["Identifiez l'accumulation", "Observez la manipulation", "Entrez en distribution", "Utilisez les Kill Zones", "Combinez avec OB/FVG"], example: "Range asiatique 1.0850-1.0870. Manipulation à 1.0840. Distribution vers 1.0920.", keyTakeaways: ["AMD = 3 phases", "Accumulation = Asie", "Manipulation = faux breakout", "Distribution = vrai mouvement"] }, es: { title: "Power of Three ICT (AMD)", content: "AMD: Acumulación (Asia), Manipulación (falso breakout), Distribución (el movimiento real).", steps: ["Identifica la acumulación", "Observa la manipulación", "Entra en distribución", "Usa las Kill Zones", "Combina con OB/FVG"], example: "Rango asiático 1.0850-1.0870. Manipulación a 1.0840. Distribución hacia 1.0920.", keyTakeaways: ["AMD = 3 fases", "Acumulación = Asia", "Manipulación = falso breakout", "Distribución = movimiento real"] } },
  { id: 9, diagram: 'entry-model', en: { title: "ICT Silver Bullet Strategy", content: "The Silver Bullet is a specific ICT entry model that focuses on FVGs created during Kill Zone times:\n\n**Silver Bullet Windows:**\n- 10:00 AM - 11:00 AM EST (NY AM)\n- 2:00 PM - 3:00 PM EST (NY PM)\n- 3:00 AM - 4:00 AM EST (London)\n\nDuring these windows, look for a displacement move that creates an FVG, then enter at the FVG.", steps: ["Set alerts for Silver Bullet windows", "Wait for a strong displacement move during the window", "Identify the FVG created by the displacement", "Enter at the FVG when price returns to it", "SL beyond the displacement candle, TP at opposing liquidity"], example: "At 10:15 AM EST, EUR/USD drops sharply creating a bearish FVG at 1.0880-1.0890. Price pulls back to 1.0885 (FVG). Enter short, SL 1.0900, TP 1.0830.", keyTakeaways: ["Silver Bullet = FVG entry during specific times", "Three daily windows", "Wait for displacement + FVG", "Simple but effective strategy"] }, ar: { title: "استراتيجية الرصاصة الفضية", content: "الرصاصة الفضية هي نموذج دخول ICT محدد يركز على FVG المتشكلة خلال أوقات مناطق القتل:\n\n**نوافذ الرصاصة الفضية:**\n- 10:00 ص - 11:00 ص EST\n- 2:00 م - 3:00 م EST\n- 3:00 ص - 4:00 ص EST", steps: ["ضع تنبيهات لنوافذ الرصاصة الفضية", "انتظر حركة إزاحة قوية خلال النافذة", "حدد FVG الناتج عن الإزاحة", "ادخل عند عودة السعر للفجوة", "SL وراء شمعة الإزاحة، TP عند السيولة المعاكسة"], example: "عند 10:15 ص EST، EUR/USD يهبط بقوة مشكلاً FVG هبوطي عند 1.0880-1.0890. السعر يتراجع لـ 1.0885. ادخل بيع.", keyTakeaways: ["الرصاصة الفضية = دخول FVG في أوقات محددة", "ثلاث نوافذ يومية", "انتظر إزاحة + FVG", "استراتيجية بسيطة لكن فعالة"] }, fr: { title: "Stratégie Silver Bullet", content: "Silver Bullet = entrée FVG pendant des fenêtres temporelles spécifiques (10-11h, 14-15h, 3-4h EST).", steps: ["Alertes pour les fenêtres", "Attendez le déplacement", "Identifiez le FVG", "Entrez au FVG", "SL au-delà du déplacement"], example: "10:15 EST, EUR/USD chute créant FVG baissier à 1.0880-1.0890. Vente à 1.0885.", keyTakeaways: ["Silver Bullet = FVG + timing", "Trois fenêtres", "Déplacement + FVG", "Simple et efficace"] }, es: { title: "Estrategia Silver Bullet", content: "Silver Bullet = entrada FVG durante ventanas temporales específicas (10-11h, 14-15h, 3-4h EST).", steps: ["Alertas para las ventanas", "Espera el desplazamiento", "Identifica el FVG", "Entra en el FVG", "SL más allá del desplazamiento"], example: "10:15 EST, EUR/USD cae creando FVG bajista en 1.0880-1.0890. Venta en 1.0885.", keyTakeaways: ["Silver Bullet = FVG + timing", "Tres ventanas", "Desplazamiento + FVG", "Simple y efectiva"] } },
  { id: 10, diagram: 'risk-management', en: { title: "ICT Risk Management", content: "ICT risk management emphasizes precision entries for tight stop losses:\n\n1. **SL Placement:** Always beyond the order block or FVG that triggered your entry\n2. **TP Targets:** Previous liquidity pools (BSL/SSL)\n3. **Risk per trade:** 1-2% maximum\n4. **Daily loss limit:** 3-5% maximum\n5. **Partial profits:** Take 50% at 1:2, let rest run to 1:4+", steps: ["Calculate position size before every trade", "Place SL at the invalidation point", "Target opposing liquidity for TP", "Take partial profits at 1:2 RR", "Move SL to breakeven after partial close", "Stop trading after daily loss limit"], example: "Entry at OB 1.0850, SL at 1.0830 (20 pips). TP1 at 1.0890 (1:2, close 50%). TP2 at 1.0930 (1:4, close remaining). Move SL to 1.0850 after TP1.", keyTakeaways: ["Precision entries = tight stops", "Target liquidity for TP", "Partial profits protect capital", "Daily loss limits prevent blowups"] }, ar: { title: "إدارة المخاطر في ICT", content: "إدارة المخاطر في ICT تؤكد على الدخول الدقيق لوقف خسارة ضيق:\n\n1. **وضع SL:** دائماً وراء OB أو FVG\n2. **أهداف TP:** تجمعات السيولة السابقة\n3. **مخاطرة لكل صفقة:** 1-2% كحد أقصى\n4. **حد الخسارة اليومي:** 3-5% كحد أقصى\n5. **أرباح جزئية:** خذ 50% عند 1:2", steps: ["احسب حجم المركز قبل كل صفقة", "ضع SL عند نقطة الإبطال", "استهدف السيولة المعاكسة لـ TP", "خذ أرباحاً جزئية عند 1:2", "حرك SL للتعادل بعد الإغلاق الجزئي", "توقف عن التداول بعد حد الخسارة اليومي"], example: "دخول عند OB 1.0850، SL عند 1.0830 (20 نقطة). TP1 عند 1.0890 (1:2، أغلق 50%). TP2 عند 1.0930 (1:4).", keyTakeaways: ["دخول دقيق = وقف ضيق", "استهدف السيولة لـ TP", "الأرباح الجزئية تحمي رأس المال", "حدود الخسارة اليومية تمنع الانهيار"] }, fr: { title: "Gestion des Risques ICT", content: "ICT: entrées précises pour stops serrés, TP à la liquidité, partiels à 1:2.", steps: ["Calculez la taille", "SL à l'invalidation", "TP à la liquidité", "Partiels à 1:2", "SL au breakeven", "Limite de perte quotidienne"], example: "Entrée OB 1.0850, SL 1.0830, TP1 1.0890, TP2 1.0930.", keyTakeaways: ["Entrées précises", "TP à la liquidité", "Partiels protègent", "Limites quotidiennes"] }, es: { title: "Gestión de Riesgos ICT", content: "ICT: entradas precisas para stops ajustados, TP en liquidez, parciales en 1:2.", steps: ["Calcula el tamaño", "SL en invalidación", "TP en liquidez", "Parciales en 1:2", "SL a breakeven", "Límite de pérdida diaria"], example: "Entrada OB 1.0850, SL 1.0830, TP1 1.0890, TP2 1.0930.", keyTakeaways: ["Entradas precisas", "TP en liquidez", "Parciales protegen", "Límites diarios"] } },
  { id: 11, diagram: 'entry-model', en: { title: "ICT Backtesting & Journaling", content: "ICT emphasizes the importance of backtesting and keeping a detailed trading journal.\n\n**Backtesting:** Go through historical charts and practice identifying setups. Mark entries, stops, and targets. Calculate win rate and average RR.\n\n**Journaling:** Record every trade with screenshots, reasoning, emotions, and results. Review weekly to identify patterns in your trading.", steps: ["Choose a pair and go back 3-6 months on the chart", "Practice marking structure, liquidity, OBs, and FVGs", "Simulate entries and calculate results", "Keep a spreadsheet tracking all metrics", "Review your journal weekly and monthly"], example: "After backtesting 100 trades on EUR/USD using the Silver Bullet strategy, you find: 62% win rate, average RR 1:2.5, maximum drawdown 4%. This gives you confidence to trade live.", keyTakeaways: ["Backtest before trading live", "Journal every trade with details", "Review weekly for improvement", "Track win rate, RR, and drawdown"] }, ar: { title: "الاختبار الخلفي والتوثيق في ICT", content: "ICT تؤكد على أهمية الاختبار الخلفي والاحتفاظ بدفتر تداول مفصل.\n\n**الاختبار الخلفي:** راجع الرسوم البيانية التاريخية وتدرب على تحديد الفرص.\n**التوثيق:** سجل كل صفقة مع لقطات شاشة وأسباب ونتائج.", steps: ["اختر زوجاً وارجع 3-6 أشهر", "تدرب على تحديد الهيكل والسيولة وOB وFVG", "حاكِ الدخول واحسب النتائج", "احتفظ بجدول يتتبع جميع المقاييس", "راجع دفترك أسبوعياً وشهرياً"], example: "بعد اختبار 100 صفقة على EUR/USD باستراتيجية الرصاصة الفضية: نسبة فوز 62%، متوسط RR 1:2.5، أقصى تراجع 4%.", keyTakeaways: ["اختبر قبل التداول الحقيقي", "وثق كل صفقة بالتفاصيل", "راجع أسبوعياً للتحسين", "تتبع نسبة الفوز والتراجع"] }, fr: { title: "Backtesting & Journal ICT", content: "ICT insiste sur le backtesting et le journal de trading détaillé.", steps: ["Choisissez une paire", "Pratiquez le marquage", "Simulez les entrées", "Suivez les métriques", "Révisez régulièrement"], example: "100 trades backtestés: 62% win rate, RR moyen 1:2.5.", keyTakeaways: ["Backtestez d'abord", "Journalisez chaque trade", "Révisez hebdomadairement", "Suivez les métriques"] }, es: { title: "Backtesting & Diario ICT", content: "ICT enfatiza el backtesting y el diario de trading detallado.", steps: ["Elige un par", "Practica el marcado", "Simula entradas", "Sigue las métricas", "Revisa regularmente"], example: "100 trades backtested: 62% win rate, RR promedio 1:2.5.", keyTakeaways: ["Backtestea primero", "Documenta cada trade", "Revisa semanalmente", "Sigue las métricas"] } },
  { id: 12, diagram: 'entry-model', en: { title: "ICT Complete Trading Model", content: "The complete ICT trading model combines all concepts into a systematic approach:\n\n1. **Daily Bias:** Determine bullish or bearish using HTF structure and liquidity\n2. **Kill Zone Timing:** Only trade during active sessions\n3. **AMD Framework:** Identify accumulation, manipulation, distribution\n4. **Entry:** Use OTE + OB/FVG during Silver Bullet windows\n5. **Risk:** 1-2% per trade, daily limit 5%\n6. **Exit:** Target opposing liquidity, partial at 1:2", steps: ["Start each day by analyzing the Daily chart for bias", "Mark key liquidity levels on H4", "Wait for Kill Zone activation", "Identify AMD pattern forming", "Enter at OB/FVG within OTE zone", "Manage with partials and trailing SL"], example: "Daily bias: Bullish (price above key OB). H4 shows SSL at 1.0800. During NY Kill Zone, price sweeps 1.0800, CHoCH forms on M15. Bullish OB at 1.0810 within OTE. Enter long 1.0815, SL 1.0790, TP1 1.0865 (1:2), TP2 1.0915 (1:4).", keyTakeaways: ["Systematic approach removes emotions", "Multi-timeframe analysis is essential", "Kill Zones + AMD = timing edge", "OTE + OB/FVG = precision entries", "Consistent risk management = longevity"] }, ar: { title: "نموذج التداول الكامل في ICT", content: "نموذج التداول الكامل في ICT يجمع جميع المفاهيم:\n\n1. **الاتجاه اليومي:** حدد صعودي أو هبوطي\n2. **توقيت مناطق القتل:** تداول فقط في الجلسات النشطة\n3. **إطار AMD:** حدد التجميع والتلاعب والتوزيع\n4. **الدخول:** استخدم OTE + OB/FVG\n5. **المخاطرة:** 1-2% لكل صفقة\n6. **الخروج:** استهدف السيولة المعاكسة", steps: ["ابدأ كل يوم بتحليل الرسم اليومي", "حدد مستويات السيولة على H4", "انتظر تفعيل منطقة القتل", "حدد نمط AMD المتشكل", "ادخل عند OB/FVG في منطقة OTE", "أدر بإغلاقات جزئية وSL متحرك"], example: "الاتجاه اليومي: صعودي. H4 يُظهر SSL عند 1.0800. خلال منطقة قتل نيويورك، السعر يكتسح 1.0800، CHoCH يتشكل على M15. OB صعودي عند 1.0810. دخول شراء 1.0815، SL 1.0790، TP1 1.0865، TP2 1.0915.", keyTakeaways: ["النهج المنظم يزيل المشاعر", "التحليل متعدد الأطر ضروري", "مناطق القتل + AMD = ميزة التوقيت", "OTE + OB/FVG = دخول دقيق", "إدارة مخاطر مستمرة = استمرارية"] }, fr: { title: "Modèle de Trading ICT Complet", content: "Le modèle complet ICT: biais quotidien, Kill Zones, AMD, OTE + OB/FVG, gestion du risque.", steps: ["Analysez le Daily", "Marquez la liquidité H4", "Attendez les Kill Zones", "Identifiez AMD", "Entrez à OTE + OB/FVG", "Gérez avec partiels"], example: "Biais haussier. SSL H4 à 1.0800. NY sweep + CHoCH M15. OB 1.0810. Achat 1.0815.", keyTakeaways: ["Approche systématique", "Multi-TF essentiel", "Kill Zones + AMD", "OTE + OB/FVG", "Gestion du risque constante"] }, es: { title: "Modelo de Trading ICT Completo", content: "El modelo completo ICT: sesgo diario, Kill Zones, AMD, OTE + OB/FVG, gestión de riesgo.", steps: ["Analiza el Daily", "Marca liquidez H4", "Espera Kill Zones", "Identifica AMD", "Entra en OTE + OB/FVG", "Gestiona con parciales"], example: "Sesgo alcista. SSL H4 en 1.0800. NY sweep + CHoCH M15. OB 1.0810. Compra 1.0815.", keyTakeaways: ["Enfoque sistemático", "Multi-TF esencial", "Kill Zones + AMD", "OTE + OB/FVG", "Gestión de riesgo constante"] } }
];

export const skLessons = [
  { id: 1, diagram: 'trend', en: { title: "Introduction to the SK System", content: "The SK System is a unique trading methodology that combines elements from classical analysis, SMC, and ICT into a simplified, practical approach.\n\nDeveloped for traders who want a clear, rule-based system that works across all markets and timeframes. The SK System focuses on three pillars:\n\n1. **Structure First:** Always identify the market structure before anything else\n2. **Key Levels:** Find the most important price levels where institutions are active\n3. **Confirmation:** Never enter without a clear confirmation signal", steps: ["Learn the three pillars of SK System", "Understand that simplicity is the key to consistency", "Focus on high-probability setups only", "Master one setup before adding more", "Practice on demo for at least 3 months"], example: "The SK System trader starts each session by marking structure on H4, identifying 2-3 key levels, then waiting patiently for a confirmation signal at one of those levels.", keyTakeaways: ["SK System = simplified institutional trading", "Three pillars: Structure, Key Levels, Confirmation", "Simplicity leads to consistency", "Quality over quantity in setups"] }, ar: { title: "مقدمة في نظام SK", content: "نظام SK هو منهجية تداول فريدة تجمع عناصر من التحليل الكلاسيكي وSMC وICT في نهج مبسط وعملي.\n\nتم تطويره للمتداولين الذين يريدون نظاماً واضحاً قائماً على القواعد. يركز على ثلاثة أعمدة:\n\n1. **الهيكل أولاً:** حدد هيكل السوق دائماً قبل أي شيء\n2. **المستويات الرئيسية:** ابحث عن أهم مستويات الأسعار\n3. **التأكيد:** لا تدخل أبداً بدون إشارة تأكيد واضحة", steps: ["تعلم الأعمدة الثلاثة لنظام SK", "افهم أن البساطة مفتاح الاستمرارية", "ركز على الفرص عالية الاحتمالية فقط", "أتقن فرصة واحدة قبل إضافة المزيد", "تدرب على حساب تجريبي لمدة 3 أشهر على الأقل"], example: "متداول نظام SK يبدأ كل جلسة بتحديد الهيكل على H4، تحديد 2-3 مستويات رئيسية، ثم الانتظار بصبر لإشارة تأكيد.", keyTakeaways: ["نظام SK = تداول مؤسسي مبسط", "ثلاثة أعمدة: الهيكل، المستويات، التأكيد", "البساطة تؤدي للاستمرارية", "الجودة فوق الكمية"] }, fr: { title: "Introduction au Système SK", content: "Le système SK combine analyse classique, SMC et ICT en une approche simplifiée avec trois piliers: Structure, Niveaux Clés, Confirmation.", steps: ["Apprenez les trois piliers", "La simplicité est la clé", "Focus sur la haute probabilité", "Maîtrisez un setup", "Pratiquez 3 mois en démo"], example: "Le trader SK marque la structure H4, identifie 2-3 niveaux, attend la confirmation.", keyTakeaways: ["SK = trading institutionnel simplifié", "Trois piliers", "Simplicité = consistance", "Qualité > quantité"] }, es: { title: "Introducción al Sistema SK", content: "El sistema SK combina análisis clásico, SMC e ICT en un enfoque simplificado con tres pilares: Estructura, Niveles Clave, Confirmación.", steps: ["Aprende los tres pilares", "La simplicidad es la clave", "Enfócate en alta probabilidad", "Domina un setup", "Practica 3 meses en demo"], example: "El trader SK marca estructura H4, identifica 2-3 niveles, espera confirmación.", keyTakeaways: ["SK = trading institucional simplificado", "Tres pilares", "Simplicidad = consistencia", "Calidad > cantidad"] } },
  { id: 2, diagram: 'market-structure', en: { title: "SK Structure Analysis", content: "In the SK System, structure analysis is simplified into three clear states:\n\n**Trending Up:** Clear HH and HL — look for buy setups only\n**Trending Down:** Clear LH and LL — look for sell setups only\n**Ranging:** No clear direction — stay out or trade the range boundaries\n\nThe rule is simple: identify the state, then only take setups that align with it.", steps: ["Open the H4 chart and identify the current state", "Mark the last 3-4 swing points", "Determine: Trending Up, Trending Down, or Ranging", "Only take trades that align with the state", "Re-evaluate when structure changes"], example: "H4 shows clear HH at 1.1050 and HL at 1.1000. State: Trending Up. Only look for buy setups at pullbacks to HL areas.", keyTakeaways: ["Three states: Up, Down, Ranging", "Only trade with the state", "Stay out during ranging if unsure", "Re-evaluate on structure change"] }, ar: { title: "تحليل الهيكل في SK", content: "في نظام SK، تحليل الهيكل مبسط إلى ثلاث حالات:\n\n**اتجاه صاعد:** HH و HL واضحة — ابحث عن فرص شراء فقط\n**اتجاه هابط:** LH و LL واضحة — ابحث عن فرص بيع فقط\n**نطاق:** لا اتجاه واضح — ابتعد أو تداول حدود النطاق", steps: ["افتح رسم H4 وحدد الحالة الحالية", "حدد آخر 3-4 نقاط تأرجح", "حدد: صاعد، هابط، أو نطاق", "خذ فقط الصفقات المتوافقة مع الحالة", "أعد التقييم عند تغيير الهيكل"], example: "H4 يُظهر HH عند 1.1050 و HL عند 1.1000. الحالة: صاعد. ابحث فقط عن فرص شراء.", keyTakeaways: ["ثلاث حالات: صاعد، هابط، نطاق", "تداول فقط مع الحالة", "ابتعد أثناء النطاق إذا لم تكن متأكداً", "أعد التقييم عند تغيير الهيكل"] }, fr: { title: "Analyse de Structure SK", content: "SK simplifie en trois états: Hausse, Baisse, Range. Tradez uniquement avec l'état.", steps: ["Ouvrez H4", "Marquez les swings", "Déterminez l'état", "Tradez avec l'état", "Réévaluez au changement"], example: "H4 montre HH et HL. État: Hausse. Achetez uniquement.", keyTakeaways: ["Trois états", "Tradez avec l'état", "Restez dehors en range", "Réévaluez"] }, es: { title: "Análisis de Estructura SK", content: "SK simplifica en tres estados: Alcista, Bajista, Rango. Opera solo con el estado.", steps: ["Abre H4", "Marca los swings", "Determina el estado", "Opera con el estado", "Reevalúa al cambio"], example: "H4 muestra HH y HL. Estado: Alcista. Solo compra.", keyTakeaways: ["Tres estados", "Opera con el estado", "Fuera en rango", "Reevalúa"] } },
  { id: 3, diagram: 'support-resistance', en: { title: "SK Key Levels", content: "The SK System identifies three types of key levels:\n\n**Institutional Levels:** Major round numbers (1.0800, 1.0900, 1.1000) where banks place large orders\n**Reaction Levels:** Areas where price has shown strong reactions in the past (multiple bounces)\n**Fresh Levels:** Order blocks and FVGs that haven't been tested yet\n\nThe best setups occur when multiple level types overlap (confluence).", steps: ["Mark institutional levels (round numbers)", "Identify reaction levels from recent price history", "Find fresh OBs and FVGs", "Look for confluence (2+ levels overlapping)", "Only trade at levels with confluence"], example: "1.0900 is an institutional level. There's also a bullish OB at 1.0895-1.0905 and price has bounced from this area twice before. This triple confluence makes it a high-probability buy zone.", keyTakeaways: ["Three level types: Institutional, Reaction, Fresh", "Confluence = multiple levels overlapping", "Trade only at confluence zones", "More confluence = higher probability"] }, ar: { title: "المستويات الرئيسية في SK", content: "نظام SK يحدد ثلاثة أنواع من المستويات الرئيسية:\n\n**المستويات المؤسسية:** الأرقام الدائرية الكبرى حيث تضع البنوك أوامر كبيرة\n**مستويات التفاعل:** مناطق أظهر فيها السعر ردود فعل قوية سابقاً\n**المستويات الطازجة:** كتل أوامر وFVG لم تُختبر بعد\n\nأفضل الفرص تحدث عند تقاطع أنواع متعددة (التقاء).", steps: ["حدد المستويات المؤسسية (الأرقام الدائرية)", "حدد مستويات التفاعل من تاريخ السعر", "ابحث عن OB وFVG طازجة", "ابحث عن التقاء (2+ مستويات متداخلة)", "تداول فقط عند مناطق الالتقاء"], example: "1.0900 مستوى مؤسسي. هناك أيضاً OB صعودي عند 1.0895-1.0905 والسعر ارتد من هذه المنطقة مرتين. هذا التقاء ثلاثي يجعلها منطقة شراء عالية الاحتمالية.", keyTakeaways: ["ثلاثة أنواع: مؤسسية، تفاعل، طازجة", "الالتقاء = تداخل مستويات متعددة", "تداول فقط عند مناطق الالتقاء", "التقاء أكثر = احتمالية أعلى"] }, fr: { title: "Niveaux Clés SK", content: "SK identifie trois types: Institutionnels (nombres ronds), Réaction (rebonds passés), Frais (OB/FVG non testés). La confluence est la clé.", steps: ["Marquez les niveaux institutionnels", "Identifiez les réactions", "Trouvez les niveaux frais", "Cherchez la confluence", "Tradez à la confluence"], example: "1.0900 institutionnel + OB + double rebond = triple confluence.", keyTakeaways: ["Trois types de niveaux", "Confluence = chevauchement", "Tradez à la confluence", "Plus de confluence = plus de probabilité"] }, es: { title: "Niveles Clave SK", content: "SK identifica tres tipos: Institucionales (números redondos), Reacción (rebotes pasados), Frescos (OB/FVG no probados). La confluencia es la clave.", steps: ["Marca niveles institucionales", "Identifica reacciones", "Encuentra niveles frescos", "Busca confluencia", "Opera en confluencia"], example: "1.0900 institucional + OB + doble rebote = triple confluencia.", keyTakeaways: ["Tres tipos de niveles", "Confluencia = superposición", "Opera en confluencia", "Más confluencia = más probabilidad"] } },
  { id: 4, diagram: 'candlestick', en: { title: "SK Confirmation Signals", content: "The SK System uses specific confirmation signals before entering any trade:\n\n**Level 1 - Candle Confirmation:** Engulfing, pin bar, or doji at a key level\n**Level 2 - Structure Confirmation:** BOS or CHoCH on the entry timeframe\n**Level 3 - Volume Confirmation:** Increased volume at the key level (if available)\n\nYou need at least Level 1 + Level 2 confirmation before entering.", steps: ["Wait for price to reach a key level with confluence", "Look for a Level 1 candle signal", "Confirm with Level 2 structure shift", "Check volume if available (Level 3)", "Enter only when 2+ confirmations align"], example: "Price reaches bullish OB at 1.0850 (key level). A bullish engulfing candle forms (Level 1). M15 shows BOS above recent high (Level 2). Enter long with confidence.", keyTakeaways: ["Three confirmation levels", "Need minimum 2 confirmations", "Candle + Structure = minimum requirement", "Volume adds extra confidence"] }, ar: { title: "إشارات التأكيد في SK", content: "نظام SK يستخدم إشارات تأكيد محددة قبل الدخول:\n\n**المستوى 1 - تأكيد الشمعة:** ابتلاع، دبوس، أو دوجي عند مستوى رئيسي\n**المستوى 2 - تأكيد الهيكل:** BOS أو CHoCH على إطار الدخول\n**المستوى 3 - تأكيد الحجم:** زيادة الحجم عند المستوى الرئيسي\n\nتحتاج على الأقل المستوى 1 + المستوى 2 قبل الدخول.", steps: ["انتظر وصول السعر لمستوى رئيسي مع التقاء", "ابحث عن إشارة شمعة المستوى 1", "أكد بتحول هيكل المستوى 2", "تحقق من الحجم إن توفر (المستوى 3)", "ادخل فقط عند توافق 2+ تأكيدات"], example: "السعر يصل لـ OB صعودي عند 1.0850. شمعة ابتلاع صعودية تتشكل (المستوى 1). M15 يُظهر BOS (المستوى 2). ادخل شراء بثقة.", keyTakeaways: ["ثلاثة مستويات تأكيد", "تحتاج حد أدنى تأكيدين", "شمعة + هيكل = الحد الأدنى", "الحجم يضيف ثقة إضافية"] }, fr: { title: "Signaux de Confirmation SK", content: "SK utilise trois niveaux de confirmation: Bougie, Structure, Volume. Minimum 2 niveaux requis.", steps: ["Attendez le niveau clé", "Cherchez signal bougie", "Confirmez la structure", "Vérifiez le volume", "Entrez avec 2+ confirmations"], example: "OB à 1.0850 + englobante haussière + BOS M15 = entrée.", keyTakeaways: ["Trois niveaux", "Minimum 2", "Bougie + Structure minimum", "Volume = bonus"] }, es: { title: "Señales de Confirmación SK", content: "SK usa tres niveles de confirmación: Vela, Estructura, Volumen. Mínimo 2 niveles requeridos.", steps: ["Espera el nivel clave", "Busca señal de vela", "Confirma estructura", "Verifica volumen", "Entra con 2+ confirmaciones"], example: "OB en 1.0850 + envolvente alcista + BOS M15 = entrada.", keyTakeaways: ["Tres niveles", "Mínimo 2", "Vela + Estructura mínimo", "Volumen = bonus"] } },
  { id: 5, diagram: 'entry-model', en: { title: "SK Trade Setup Process", content: "The SK System follows a strict 5-step process for every trade:\n\n**Step 1:** Identify the state (Up/Down/Range) on H4\n**Step 2:** Mark 2-3 key levels with confluence\n**Step 3:** Wait for price to reach a key level\n**Step 4:** Get confirmation (candle + structure)\n**Step 5:** Execute with proper risk management\n\nIf any step is missing, don't take the trade.", steps: ["Check H4 for state determination", "Mark key levels with at least 2 confluences", "Set alerts at key levels and wait", "When alerted, switch to M15 for confirmation", "Execute with 1% risk, SL beyond level, TP at next liquidity"], example: "Step 1: H4 trending up. Step 2: Key level at 1.0850 (OB + institutional + reaction). Step 3: Price pulls back to 1.0850. Step 4: Bullish engulfing + M15 BOS. Step 5: Buy 1.0855, SL 1.0830, TP 1.0920.", keyTakeaways: ["5-step process for every trade", "Skip no steps", "If any step fails, skip the trade", "Discipline is everything"] }, ar: { title: "عملية إعداد صفقة SK", content: "نظام SK يتبع عملية صارمة من 5 خطوات لكل صفقة:\n\n**الخطوة 1:** حدد الحالة على H4\n**الخطوة 2:** حدد 2-3 مستويات رئيسية مع التقاء\n**الخطوة 3:** انتظر وصول السعر لمستوى رئيسي\n**الخطوة 4:** احصل على التأكيد\n**الخطوة 5:** نفذ بإدارة مخاطر سليمة\n\nإذا غابت أي خطوة، لا تأخذ الصفقة.", steps: ["تحقق من H4 لتحديد الحالة", "حدد المستويات مع التقاءين على الأقل", "ضع تنبيهات وانتظر", "عند التنبيه، انتقل لـ M15 للتأكيد", "نفذ بمخاطرة 1%"], example: "الخطوة 1: H4 صاعد. الخطوة 2: مستوى عند 1.0850. الخطوة 3: السعر يتراجع لـ 1.0850. الخطوة 4: ابتلاع + BOS. الخطوة 5: شراء 1.0855، SL 1.0830، TP 1.0920.", keyTakeaways: ["عملية من 5 خطوات لكل صفقة", "لا تتخطَ أي خطوة", "إذا فشلت أي خطوة، تخطَ الصفقة", "الانضباط هو كل شيء"] }, fr: { title: "Processus de Setup SK", content: "SK suit un processus strict en 5 étapes pour chaque trade.", steps: ["Vérifiez H4", "Marquez les niveaux", "Attendez le prix", "Obtenez confirmation", "Exécutez avec risque 1%"], example: "H4 haussier. Niveau 1.0850. Pullback + englobante + BOS. Achat 1.0855.", keyTakeaways: ["5 étapes", "Ne sautez rien", "Si une étape échoue, passez", "Discipline"] }, es: { title: "Proceso de Setup SK", content: "SK sigue un proceso estricto de 5 pasos para cada operación.", steps: ["Verifica H4", "Marca niveles", "Espera el precio", "Obtén confirmación", "Ejecuta con riesgo 1%"], example: "H4 alcista. Nivel 1.0850. Pullback + envolvente + BOS. Compra 1.0855.", keyTakeaways: ["5 pasos", "No saltes nada", "Si un paso falla, pasa", "Disciplina"] } },
  { id: 6, diagram: 'risk-management', en: { title: "SK Risk Management Rules", content: "The SK System has strict risk management rules that must never be broken:\n\n**The SK Risk Rules:**\n1. Risk exactly 1% per trade (never more)\n2. Maximum 2 trades per day\n3. Stop trading after 2 consecutive losses\n4. Weekly loss limit: 5%\n5. Monthly loss limit: 10%\n6. Always use a stop loss (no exceptions)\n7. Minimum 1:2 risk-to-reward ratio\n8. Never move stop loss further from entry\n9. Take partial profits at 1:2\n10. Move SL to breakeven after partial close", steps: ["Memorize all 10 rules", "Calculate position size for exactly 1% risk", "Track daily, weekly, and monthly P&L", "Stop immediately when limits are hit", "Review performance every weekend"], example: "Account: $5,000. Risk per trade: 1% = $50. Stop loss: 25 pips. Lot size = $50 / (25 × $10) = 0.20 lots. Maximum daily loss: $100 (2 trades × $50).", keyTakeaways: ["10 strict rules — never break them", "1% risk per trade maximum", "2 trades per day maximum", "Weekly and monthly limits protect your account"] }, ar: { title: "قواعد إدارة المخاطر في SK", content: "نظام SK لديه قواعد صارمة لإدارة المخاطر لا يجب كسرها أبداً:\n\n1. خاطر بـ 1% بالضبط لكل صفقة\n2. حد أقصى صفقتين يومياً\n3. توقف بعد خسارتين متتاليتين\n4. حد خسارة أسبوعي: 5%\n5. حد خسارة شهري: 10%\n6. استخدم دائماً وقف الخسارة\n7. حد أدنى نسبة 1:2\n8. لا تحرك وقف الخسارة بعيداً\n9. خذ أرباحاً جزئية عند 1:2\n10. حرك SL للتعادل بعد الإغلاق الجزئي", steps: ["احفظ جميع القواعد العشر", "احسب حجم المركز لمخاطرة 1% بالضبط", "تتبع الأرباح والخسائر يومياً وأسبوعياً وشهرياً", "توقف فوراً عند بلوغ الحدود", "راجع الأداء كل عطلة نهاية أسبوع"], example: "حساب: $5,000. مخاطرة لكل صفقة: 1% = $50. وقف خسارة: 25 نقطة. حجم اللوت = $50 / (25 × $10) = 0.20 لوت.", keyTakeaways: ["10 قواعد صارمة — لا تكسرها أبداً", "مخاطرة 1% لكل صفقة كحد أقصى", "صفقتين يومياً كحد أقصى", "الحدود الأسبوعية والشهرية تحمي حسابك"] }, fr: { title: "Règles de Gestion des Risques SK", content: "SK a 10 règles strictes de gestion du risque.", steps: ["Mémorisez les 10 règles", "Calculez la taille", "Suivez le P&L", "Arrêtez aux limites", "Révisez chaque weekend"], example: "Compte $5,000. Risque 1% = $50. SL 25 pips. Taille = 0.20 lots.", keyTakeaways: ["10 règles strictes", "1% par trade", "2 trades par jour", "Limites protègent"] }, es: { title: "Reglas de Gestión de Riesgos SK", content: "SK tiene 10 reglas estrictas de gestión de riesgo.", steps: ["Memoriza las 10 reglas", "Calcula el tamaño", "Sigue el P&L", "Para en los límites", "Revisa cada fin de semana"], example: "Cuenta $5,000. Riesgo 1% = $50. SL 25 pips. Tamaño = 0.20 lotes.", keyTakeaways: ["10 reglas estrictas", "1% por trade", "2 trades por día", "Límites protegen"] } },
  { id: 7, diagram: 'entry-model', en: { title: "SK Multi-Timeframe Analysis", content: "The SK System uses a simple 3-timeframe approach:\n\n**H4 (Direction):** Determines the overall trend direction. This is your compass.\n**H1 (Context):** Shows the current market context — is price at a key level?\n**M15 (Entry):** The execution timeframe where you look for confirmation and enter.\n\nNever trade on M15 alone. Always start from H4 down to M15.", steps: ["Start with H4 to determine direction", "Switch to H1 to find key levels and context", "Move to M15 only when price is at a key level", "Look for confirmation on M15", "Execute the trade on M15"], example: "H4: Bullish trend. H1: Price pulling back to a key OB at 1.0850. M15: Bullish engulfing + BOS at 1.0855. Enter long on M15.", keyTakeaways: ["H4 = Direction (compass)", "H1 = Context (key levels)", "M15 = Entry (execution)", "Always top-down analysis"] }, ar: { title: "التحليل متعدد الأطر في SK", content: "نظام SK يستخدم نهج 3 أطر زمنية بسيط:\n\n**H4 (الاتجاه):** يحدد اتجاه الترند العام. هذا بوصلتك.\n**H1 (السياق):** يُظهر سياق السوق الحالي.\n**M15 (الدخول):** إطار التنفيذ حيث تبحث عن التأكيد وتدخل.", steps: ["ابدأ بـ H4 لتحديد الاتجاه", "انتقل لـ H1 لإيجاد المستويات والسياق", "انتقل لـ M15 فقط عند المستوى الرئيسي", "ابحث عن التأكيد على M15", "نفذ الصفقة على M15"], example: "H4: اتجاه صاعد. H1: السعر يتراجع لـ OB عند 1.0850. M15: ابتلاع صعودي + BOS عند 1.0855. ادخل شراء.", keyTakeaways: ["H4 = الاتجاه (البوصلة)", "H1 = السياق (المستويات)", "M15 = الدخول (التنفيذ)", "دائماً تحليل من الأعلى للأسفل"] }, fr: { title: "Analyse Multi-Timeframe SK", content: "SK utilise 3 timeframes: H4 (direction), H1 (contexte), M15 (entrée).", steps: ["H4 pour la direction", "H1 pour le contexte", "M15 pour l'entrée", "Confirmation M15", "Exécution M15"], example: "H4 haussier. H1 pullback OB 1.0850. M15 englobante + BOS.", keyTakeaways: ["H4 = direction", "H1 = contexte", "M15 = entrée", "Top-down toujours"] }, es: { title: "Análisis Multi-Timeframe SK", content: "SK usa 3 timeframes: H4 (dirección), H1 (contexto), M15 (entrada).", steps: ["H4 para dirección", "H1 para contexto", "M15 para entrada", "Confirmación M15", "Ejecución M15"], example: "H4 alcista. H1 pullback OB 1.0850. M15 envolvente + BOS.", keyTakeaways: ["H4 = dirección", "H1 = contexto", "M15 = entrada", "Top-down siempre"] } },
  { id: 8, diagram: 'candlestick', en: { title: "SK Candlestick Mastery", content: "The SK System focuses on only 4 key candlestick patterns for confirmation:\n\n**1. Engulfing:** A candle that completely engulfs the previous candle. Strong reversal signal.\n**2. Pin Bar:** Long wick showing rejection of a level. The wick should be 2x+ the body.\n**3. Inside Bar:** A candle contained within the previous candle. Shows consolidation before a move.\n**4. Momentum Candle:** A large-bodied candle with small wicks. Shows strong directional pressure.\n\nDon't overcomplicate it — these 4 patterns are all you need.", steps: ["Learn to identify each pattern instantly", "Look for them at key levels only", "Bullish patterns at support/demand zones", "Bearish patterns at resistance/supply zones", "Combine with structure confirmation"], example: "Price reaches a bullish OB at 1.0850. A bullish engulfing candle forms on M15. This is your Level 1 confirmation. Now look for BOS on M15 for Level 2.", keyTakeaways: ["Only 4 patterns needed", "Engulfing = strongest signal", "Pin Bar = rejection signal", "Only valid at key levels"] }, ar: { title: "إتقان الشموع في SK", content: "نظام SK يركز على 4 أنماط شموع رئيسية فقط:\n\n**1. الابتلاع:** شمعة تبتلع الشمعة السابقة بالكامل.\n**2. الدبوس:** ذيل طويل يُظهر رفض مستوى.\n**3. الشمعة الداخلية:** شمعة محتواة داخل الشمعة السابقة.\n**4. شمعة الزخم:** شمعة كبيرة الجسم بذيول صغيرة.", steps: ["تعلم تحديد كل نمط فوراً", "ابحث عنها عند المستويات الرئيسية فقط", "أنماط صعودية عند مناطق الدعم/الطلب", "أنماط هبوطية عند مناطق المقاومة/العرض", "ادمج مع تأكيد الهيكل"], example: "السعر يصل لـ OB صعودي عند 1.0850. شمعة ابتلاع صعودية تتشكل على M15. هذا تأكيد المستوى 1.", keyTakeaways: ["4 أنماط فقط مطلوبة", "الابتلاع = أقوى إشارة", "الدبوس = إشارة رفض", "صالحة فقط عند المستويات الرئيسية"] }, fr: { title: "Maîtrise des Bougies SK", content: "SK se concentre sur 4 patterns: Englobante, Pin Bar, Inside Bar, Bougie de Momentum.", steps: ["Apprenez chaque pattern", "Aux niveaux clés uniquement", "Haussiers au support", "Baissiers à la résistance", "Combinez avec la structure"], example: "OB à 1.0850 + englobante haussière M15 = confirmation.", keyTakeaways: ["4 patterns suffisent", "Englobante = plus forte", "Pin Bar = rejet", "Aux niveaux clés"] }, es: { title: "Dominio de Velas SK", content: "SK se enfoca en 4 patrones: Envolvente, Pin Bar, Inside Bar, Vela de Momentum.", steps: ["Aprende cada patrón", "Solo en niveles clave", "Alcistas en soporte", "Bajistas en resistencia", "Combina con estructura"], example: "OB en 1.0850 + envolvente alcista M15 = confirmación.", keyTakeaways: ["4 patrones bastan", "Envolvente = más fuerte", "Pin Bar = rechazo", "En niveles clave"] } },
  { id: 9, diagram: 'entry-model', en: { title: "SK Trading Psychology", content: "The SK System places heavy emphasis on trading psychology:\n\n**The 3 Enemies:**\n1. **Fear:** Causes you to miss good setups or exit too early\n2. **Greed:** Causes you to overtrade or hold too long\n3. **Revenge:** Causes you to chase losses with bigger positions\n\n**The SK Mindset Rules:**\n- Accept that losses are part of the game\n- Focus on the process, not individual results\n- Take breaks after losses\n- Celebrate discipline, not profits\n- Review your journal weekly", steps: ["Identify which enemy affects you most", "Create rules to combat each enemy", "Follow the 2-loss daily stop rule strictly", "Journal your emotions alongside your trades", "Take a 24-hour break after hitting daily loss limit"], example: "You lose 2 trades in a row. Instead of revenge trading, you close your charts, review your journal, and come back tomorrow fresh. This discipline saves your account.", keyTakeaways: ["3 enemies: Fear, Greed, Revenge", "Discipline > Profits", "2-loss daily stop rule", "Journal emotions, not just trades"] }, ar: { title: "سيكولوجية التداول في SK", content: "نظام SK يركز بشدة على سيكولوجية التداول:\n\n**الأعداء الثلاثة:**\n1. **الخوف:** يجعلك تفوت فرصاً جيدة\n2. **الطمع:** يجعلك تتداول بإفراط\n3. **الانتقام:** يجعلك تطارد الخسائر بمراكز أكبر\n\n**قواعد عقلية SK:**\n- تقبل أن الخسائر جزء من اللعبة\n- ركز على العملية لا النتائج الفردية\n- خذ استراحة بعد الخسائر\n- احتفل بالانضباط لا الأرباح", steps: ["حدد أي عدو يؤثر عليك أكثر", "ضع قواعد لمحاربة كل عدو", "اتبع قاعدة التوقف بعد خسارتين بصرامة", "وثق مشاعرك مع صفقاتك", "خذ استراحة 24 ساعة بعد بلوغ حد الخسارة"], example: "خسرت صفقتين متتاليتين. بدلاً من التداول الانتقامي، أغلق الرسوم وراجع دفترك وعد غداً. هذا الانضباط ينقذ حسابك.", keyTakeaways: ["3 أعداء: الخوف، الطمع، الانتقام", "الانضباط > الأرباح", "قاعدة التوقف بعد خسارتين", "وثق المشاعر لا الصفقات فقط"] }, fr: { title: "Psychologie du Trading SK", content: "SK met l'accent sur la psychologie: 3 ennemis (Peur, Cupidité, Vengeance) et des règles mentales.", steps: ["Identifiez votre ennemi", "Créez des règles", "Règle des 2 pertes", "Journalisez les émotions", "Pause après les pertes"], example: "2 pertes = fermez les charts, revenez demain.", keyTakeaways: ["3 ennemis", "Discipline > Profits", "Règle des 2 pertes", "Journalisez les émotions"] }, es: { title: "Psicología del Trading SK", content: "SK enfatiza la psicología: 3 enemigos (Miedo, Codicia, Venganza) y reglas mentales.", steps: ["Identifica tu enemigo", "Crea reglas", "Regla de 2 pérdidas", "Documenta emociones", "Pausa después de pérdidas"], example: "2 pérdidas = cierra los gráficos, regresa mañana.", keyTakeaways: ["3 enemigos", "Disciplina > Ganancias", "Regla de 2 pérdidas", "Documenta emociones"] } },
  { id: 10, diagram: 'entry-model', en: { title: "SK Real Trade Examples", content: "Let's walk through complete SK System trade examples:\n\n**Example 1: EUR/USD Buy Setup**\n- H4: Bullish trend (HH, HL)\n- H1: Price at key level 1.0850 (OB + round number + reaction zone)\n- M15: Bullish engulfing + BOS above 1.0860\n- Entry: 1.0862, SL: 1.0838 (24 pips), TP1: 1.0910 (1:2), TP2: 1.0958 (1:4)\n- Result: TP1 hit, moved SL to BE, TP2 hit. Total: +72 pips\n\n**Example 2: GBP/USD Sell Setup**\n- H4: Bearish trend (LH, LL)\n- H1: Price at key level 1.2700 (bearish OB + institutional level)\n- M15: Bearish engulfing + BOS below 1.2690\n- Entry: 1.2688, SL: 1.2712 (24 pips), TP1: 1.2640 (1:2), TP2: 1.2592 (1:4)\n- Result: TP1 hit, TP2 hit. Total: +96 pips", steps: ["Study each example carefully", "Identify the 5 steps in each trade", "Notice how all confirmations aligned", "Practice finding similar setups on your charts", "Paper trade 50 setups before going live"], example: "The key to these examples is patience. Both trades required waiting for ALL conditions to be met. No rushing, no forcing.", keyTakeaways: ["Real examples show the system in action", "All 5 steps must be present", "Patience is the key ingredient", "Practice on demo before live trading"] }, ar: { title: "أمثلة صفقات حقيقية في SK", content: "لنستعرض أمثلة صفقات كاملة بنظام SK:\n\n**مثال 1: شراء EUR/USD**\n- H4: اتجاه صاعد\n- H1: السعر عند مستوى 1.0850 (OB + رقم دائري + منطقة تفاعل)\n- M15: ابتلاع صعودي + BOS فوق 1.0860\n- الدخول: 1.0862، SL: 1.0838، TP1: 1.0910 (1:2)، TP2: 1.0958 (1:4)\n- النتيجة: +72 نقطة\n\n**مثال 2: بيع GBP/USD**\n- H4: اتجاه هابط\n- الدخول: 1.2688، SL: 1.2712\n- النتيجة: +96 نقطة", steps: ["ادرس كل مثال بعناية", "حدد الخطوات الخمس في كل صفقة", "لاحظ كيف توافقت جميع التأكيدات", "تدرب على إيجاد فرص مشابهة", "تداول ورقياً 50 فرصة قبل الحقيقي"], example: "المفتاح في هذه الأمثلة هو الصبر. كلتا الصفقتين تطلبتا انتظار تحقق جميع الشروط.", keyTakeaways: ["الأمثلة الحقيقية تُظهر النظام عملياً", "جميع الخطوات الخمس يجب أن تكون موجودة", "الصبر هو المكون الأساسي", "تدرب على حساب تجريبي أولاً"] }, fr: { title: "Exemples de Trades Réels SK", content: "Exemples complets de trades SK avec les 5 étapes.", steps: ["Étudiez chaque exemple", "Identifiez les 5 étapes", "Notez les confirmations", "Pratiquez sur vos charts", "50 trades papier d'abord"], example: "La patience est la clé. Toutes les conditions doivent être remplies.", keyTakeaways: ["Exemples réels", "5 étapes présentes", "Patience essentielle", "Démo d'abord"] }, es: { title: "Ejemplos de Trades Reales SK", content: "Ejemplos completos de trades SK con los 5 pasos.", steps: ["Estudia cada ejemplo", "Identifica los 5 pasos", "Nota las confirmaciones", "Practica en tus gráficos", "50 trades papel primero"], example: "La paciencia es la clave. Todas las condiciones deben cumplirse.", keyTakeaways: ["Ejemplos reales", "5 pasos presentes", "Paciencia esencial", "Demo primero"] } },
  { id: 11, diagram: 'risk-management', en: { title: "SK Trading Plan Template", content: "Every SK trader must have a written trading plan. Here's the template:\n\n**1. Market:** Which pairs/assets do you trade?\n**2. Session:** Which Kill Zones do you focus on?\n**3. Direction:** How do you determine bias? (H4 structure)\n**4. Entry:** What are your entry criteria? (Key level + confirmation)\n**5. Exit:** Where do you place SL and TP?\n**6. Risk:** How much do you risk per trade? (1%)\n**7. Rules:** What are your daily/weekly limits?\n**8. Review:** When do you review your performance?\n\nPrint this plan and keep it next to your screen.", steps: ["Fill out each section honestly", "Be specific — no vague answers", "Print it and keep it visible", "Follow it religiously", "Update it monthly based on your journal"], example: "My Plan: I trade EUR/USD and GBP/USD during NY Kill Zone. I use H4 for direction, H1 for levels, M15 for entry. I risk 1% per trade, max 2 trades/day. I review every Sunday.", keyTakeaways: ["Written plan is mandatory", "Be specific and detailed", "Follow it without exception", "Update monthly based on results"] }, ar: { title: "قالب خطة التداول في SK", content: "كل متداول SK يجب أن يملك خطة تداول مكتوبة:\n\n1. **السوق:** أي أزواج/أصول تتداول؟\n2. **الجلسة:** أي مناطق قتل تركز عليها؟\n3. **الاتجاه:** كيف تحدد الاتجاه؟\n4. **الدخول:** ما معايير دخولك؟\n5. **الخروج:** أين تضع SL و TP؟\n6. **المخاطرة:** كم تخاطر لكل صفقة؟\n7. **القواعد:** ما حدودك اليومية/الأسبوعية؟\n8. **المراجعة:** متى تراجع أداءك؟", steps: ["املأ كل قسم بصدق", "كن محدداً — لا إجابات غامضة", "اطبعها واجعلها مرئية", "اتبعها بدقة", "حدثها شهرياً بناءً على دفترك"], example: "خطتي: أتداول EUR/USD و GBP/USD خلال منطقة قتل نيويورك. أستخدم H4 للاتجاه، H1 للمستويات، M15 للدخول. أخاطر بـ 1%، حد أقصى صفقتين/يوم. أراجع كل أحد.", keyTakeaways: ["الخطة المكتوبة إلزامية", "كن محدداً ومفصلاً", "اتبعها بدون استثناء", "حدثها شهرياً"] }, fr: { title: "Template de Plan de Trading SK", content: "Chaque trader SK doit avoir un plan écrit avec 8 sections.", steps: ["Remplissez chaque section", "Soyez spécifique", "Imprimez-le", "Suivez-le", "Mettez à jour mensuellement"], example: "Mon plan: EUR/USD et GBP/USD pendant NY Kill Zone. 1% risque, 2 trades/jour.", keyTakeaways: ["Plan écrit obligatoire", "Spécifique et détaillé", "Suivez sans exception", "Mise à jour mensuelle"] }, es: { title: "Plantilla de Plan de Trading SK", content: "Cada trader SK debe tener un plan escrito con 8 secciones.", steps: ["Llena cada sección", "Sé específico", "Imprímelo", "Síguelo", "Actualiza mensualmente"], example: "Mi plan: EUR/USD y GBP/USD durante NY Kill Zone. 1% riesgo, 2 trades/día.", keyTakeaways: ["Plan escrito obligatorio", "Específico y detallado", "Sigue sin excepción", "Actualización mensual"] } },
  { id: 12, diagram: 'entry-model', en: { title: "SK System Mastery Path", content: "The path to mastering the SK System:\n\n**Month 1-2: Foundation**\n- Learn all concepts thoroughly\n- Practice marking structure, levels, and patterns\n- Paper trade only\n\n**Month 3-4: Demo Trading**\n- Apply the system on a demo account\n- Follow all rules strictly\n- Journal every trade\n\n**Month 5-6: Small Live**\n- Start with minimum lot sizes\n- Focus on consistency, not profits\n- Continue journaling\n\n**Month 7+: Scaling**\n- Gradually increase position sizes\n- Only scale after 3 consecutive profitable months\n- Never skip the process", steps: ["Complete the foundation phase (2 months)", "Move to demo trading (2 months)", "Start small live trading (2 months)", "Scale gradually after proving consistency", "Never stop learning and reviewing"], example: "After 6 months of following this path, you have 200+ journal entries, a proven win rate of 55%+, and consistent 1:2+ RR. Now you're ready to scale with confidence.", keyTakeaways: ["6-month minimum before scaling", "Paper → Demo → Small Live → Scale", "Consistency before size", "Never skip steps in the process", "The journey is the destination"] }, ar: { title: "مسار إتقان نظام SK", content: "مسار إتقان نظام SK:\n\n**الشهر 1-2: الأساس**\n- تعلم جميع المفاهيم بعمق\n- تدرب على تحديد الهيكل والمستويات والأنماط\n- تداول ورقي فقط\n\n**الشهر 3-4: التداول التجريبي**\n- طبق النظام على حساب تجريبي\n- اتبع جميع القواعد بصرامة\n\n**الشهر 5-6: حقيقي صغير**\n- ابدأ بأصغر حجم لوت\n- ركز على الاستمرارية لا الأرباح\n\n**الشهر 7+: التوسع**\n- زد حجم المراكز تدريجياً\n- وسع فقط بعد 3 أشهر ربحية متتالية", steps: ["أكمل مرحلة الأساس (شهران)", "انتقل للتداول التجريبي (شهران)", "ابدأ التداول الحقيقي الصغير (شهران)", "وسع تدريجياً بعد إثبات الاستمرارية", "لا تتوقف عن التعلم والمراجعة"], example: "بعد 6 أشهر من اتباع هذا المسار، لديك 200+ تسجيل في الدفتر، نسبة فوز مثبتة 55%+، ونسبة 1:2+ مستمرة. الآن أنت جاهز للتوسع بثقة.", keyTakeaways: ["6 أشهر كحد أدنى قبل التوسع", "ورقي → تجريبي → حقيقي صغير → توسع", "الاستمرارية قبل الحجم", "لا تتخطَ خطوات العملية", "الرحلة هي الوجهة"] }, fr: { title: "Parcours de Maîtrise SK", content: "Le parcours SK: Fondation (2 mois) → Démo (2 mois) → Live petit (2 mois) → Scaling.", steps: ["Complétez la fondation", "Passez au démo", "Commencez petit en live", "Scalez graduellement", "N'arrêtez jamais d'apprendre"], example: "Après 6 mois: 200+ entrées journal, 55%+ win rate, RR 1:2+ constant.", keyTakeaways: ["6 mois minimum", "Papier → Démo → Live → Scale", "Consistance d'abord", "Ne sautez pas d'étapes", "Le voyage est la destination"] }, es: { title: "Camino de Dominio SK", content: "El camino SK: Fundación (2 meses) → Demo (2 meses) → Live pequeño (2 meses) → Scaling.", steps: ["Completa la fundación", "Pasa a demo", "Empieza pequeño en live", "Escala gradualmente", "Nunca dejes de aprender"], example: "Después de 6 meses: 200+ entradas diario, 55%+ win rate, RR 1:2+ constante.", keyTakeaways: ["6 meses mínimo", "Papel → Demo → Live → Scale", "Consistencia primero", "No saltes pasos", "El viaje es el destino"] } }
];

